import type { Dialogue, DialogueQuiz } from "@/lib/listening-dialogues";

// Phone situation C1/C2 expansion (2026-08): raises advanced coverage to 20 dialogues per level.
export const PHONE_C_EXPANSION: Dialogue[] = [
  {
    id: "phone-c1y-severance",
    situationKey: "phone",
    level: "C1",
    title: { en: "Negotiating a severance package with HR", ja: "人事部と退職金の交渉をする", zh: "与人事部协商遣散费方案", vi: "Đàm phán gói trợ cấp thôi việc với bộ phận nhân sự", es: "Negociar una indemnización por despido con Recursos Humanos" },
    lines: [
      { speaker: "인사팀", kr: "여보세요, 인사팀 박서연입니다. 어제 메일로 보내드린 퇴직 조건 관련해서 연락드렸습니다.", en: "Hello, this is Seo-yeon Park from HR. I'm calling about the severance terms I emailed yesterday.", ja: "もしもし、人事部のパク・ソヨンです。昨日メールでお送りした退職条件についてご連絡しました。", zh: "喂，我是人事部的朴瑞妍。是关于昨天邮件里发的离职条件给您打电话的。", vi: "A lô, tôi là Park Seoyeon bên phòng nhân sự. Tôi gọi để trao đổi về điều kiện thôi việc đã gửi qua email hôm qua.", es: "Hola, soy Seo-yeon Park, de Recursos Humanos. Le llamo por las condiciones de indemnización que le envié ayer por correo." },
      { speaker: "직원", kr: "네, 확인했습니다. 그런데 위로금 산정 기준이 좀 납득이 안 가서요. 근속 연수만 반영된 것 같은데요.", en: "Yes, I saw it. But I'm not quite convinced by how the payout was calculated—it seems to only factor in tenure.", ja: "はい、確認しました。ただ、慰労金の算定基準が少し納得できなくて。勤続年数だけが反映されているようなんです。", zh: "是的，我看过了。不过补偿金的计算标准我不太能理解，好像只反映了工龄。", vi: "Vâng, tôi đã xem rồi ạ. Nhưng tôi thấy tiêu chí tính khoản trợ cấp hơi khó hiểu, có vẻ chỉ tính theo số năm thâm niên.", es: "Sí, las revisé. Pero no termino de entender cómo se calculó la compensación; parece que solo se tiene en cuenta la antigüedad." },
      { speaker: "인사팀", kr: "말씀하신 부분은 저희도 재검토해 볼 여지가 있습니다. 다만 회사 규정상 직급별 배수를 벗어나기는 어렵습니다.", en: "We can look into that point again on our end. That said, it's difficult to go beyond the multiplier tied to your grade level under company policy.", ja: "おっしゃった部分は私たちも再検討する余地があります。ただ会社の規定上、職級別の倍率を超えるのは難しいです。", zh: "您说的那部分我们也有再审视的余地。不过按公司规定，很难超出按职级设定的倍数。", vi: "Phần anh/chị nói chúng tôi cũng có thể xem xét lại. Chỉ là theo quy định công ty thì khó vượt qua hệ số theo cấp bậc.", es: "Podemos volver a revisar ese punto de nuestro lado. Sin embargo, según la política de la empresa, es difícil superar el multiplicador vinculado a su categoría." },
      { speaker: "직원", kr: "그럼 이직 지원 프로그램이라도 포함해 주실 수 있을까요? 갑작스러운 통보라 준비할 시간이 부족했습니다.", en: "Could you at least include an outplacement support program then? The notice was so sudden I haven't had time to prepare.", ja: "それでは転職支援プログラムだけでも含めていただけますか? 急な通知で準備する時間が足りませんでした。", zh: "那能不能至少把转职支援计划包含进去？通知太突然了，我没有足够的时间准备。", vi: "Vậy chị có thể bổ sung thêm chương trình hỗ trợ chuyển việc không ạ? Vì thông báo quá đột ngột nên tôi không có đủ thời gian chuẩn bị.", es: "Entonces, ¿podrían incluir al menos un programa de apoyo para la recolocación laboral? El aviso fue tan repentino que no tuve tiempo de prepararme." },
      { speaker: "인사팀", kr: "일리 있는 말씀이세요. 재취업 지원 3개월 과정을 추가하는 방향으로 상부에 건의드려 보겠습니다.", en: "That's a fair point. I'll propose adding a three-month reemployment support course to management.", ja: "もっともなお話です。再就職支援の三か月コースを追加する方向で上に提案してみます。", zh: "这话有道理。我会向上级提议增加三个月的再就业支援课程。", vi: "Đó là ý kiến hợp lý. Tôi sẽ đề xuất lên cấp trên phương án bổ sung khóa hỗ trợ tái việc làm ba tháng.", es: "Es un punto razonable. Propondré a la dirección añadir un curso de apoyo a la reinserción laboral de tres meses." },
      { speaker: "직원", kr: "감사합니다. 그리고 건강보험 유지 기간도 명시해 주셨으면 하는데, 지금 서류에는 빠져 있더라고요.", en: "Thank you. Also, I'd like the health insurance continuation period specified—it's missing from the current document.", ja: "ありがとうございます。それと健康保険の維持期間も明記していただきたいのですが、今の書類には抜けていました。", zh: "谢谢。还有，希望能写明健康保险的延续期限，现在的文件里漏掉了。", vi: "Cảm ơn chị. Và tôi cũng mong chị ghi rõ thời hạn duy trì bảo hiểm y tế, vì trong hồ sơ hiện tại chưa thấy đề cập.", es: "Gracias. Además, me gustaría que se especificara el período de continuidad del seguro médico; falta en el documento actual." },
      { speaker: "인사팀", kr: "확인해 보니 누락된 게 맞네요. 규정상 두 달간 회사 부담으로 유지되니 수정본에 명확히 기재하겠습니다.", en: "You're right, it was left out. Per policy it's covered by the company for two months—I'll make sure it's clearly stated in the revised document.", ja: "確認したところ、確かに抜けていますね。規定上二か月間は会社負担で維持されますので、修正版に明確に記載します。", zh: "确认过了，确实漏了。按规定这两个月由公司承担，我会在修改版里明确写清楚。", vi: "Kiểm tra thì đúng là bị thiếu thật. Theo quy định sẽ được công ty chi trả trong hai tháng, tôi sẽ ghi rõ trong bản sửa.", es: "Tiene razón, se omitió. Según la normativa, la empresa lo cubre durante dos meses; lo dejaré claramente indicado en la versión revisada." },
      { speaker: "직원", kr: "네, 수정본 받으면 검토 후 서명하도록 하겠습니다. 최대한 빨리 부탁드릴게요.", en: "Okay, I'll review and sign once I get the revised version. Please send it as soon as possible.", ja: "はい、修正版を受け取ったら検討の上サインします。できるだけ早くお願いします。", zh: "好的，收到修改版后我会审阅后签字，请尽快发给我。", vi: "Vâng, nhận được bản sửa tôi sẽ xem lại rồi ký. Mong chị gửi sớm nhất có thể.", es: "De acuerdo, en cuanto reciba la versión revisada la revisaré y la firmaré. Le agradecería que me la enviaran lo antes posible." },
      { speaker: "인사팀", kr: "네, 내일 오전 중으로 다시 연락드리겠습니다. 협조해 주셔서 감사합니다.", en: "Sure, I'll follow up by tomorrow morning. Thank you for working with us on this.", ja: "はい、明日午前中にまたご連絡します。ご協力いただきありがとうございます。", zh: "好的，我明天上午会再联系您，感谢您的配合。", vi: "Vâng, sáng mai tôi sẽ liên hệ lại với anh. Cảm ơn anh đã hợp tác.", es: "Claro, me pondré en contacto de nuevo mañana por la mañana. Gracias por su colaboración en esto." },
    ],
  },
  {
    id: "phone-c1y-whistleblower",
    situationKey: "phone",
    level: "C1",
    title: { en: "A journalist interviews a whistleblower by phone", ja: "記者が電話で内部告発者にインタビューする", zh: "记者电话采访举报人", vi: "Nhà báo phỏng vấn người tố cáo qua điện thoại", es: "Una periodista entrevista por teléfono a un denunciante" },
    lines: [
      { speaker: "기자", kr: "여보세요, 지난번에 제보해 주신 건 관련해서 몇 가지 더 여쭤보고 싶어서 전화드렸습니다.", en: "Hello, I'm calling to ask a few more questions about the tip you gave us last time.", ja: "もしもし、以前ご提供いただいた情報について、もう少しお伺いしたくてお電話しました。", zh: "喂，是关于您之前提供的爆料，想再问几个问题所以打电话过来的。", vi: "A lô, tôi gọi để hỏi thêm vài điều về thông tin anh/chị đã cung cấp lần trước.", es: "Hola, le llamo porque quería hacerle algunas preguntas más sobre la información que nos proporcionó la vez pasada." },
      { speaker: "제보자", kr: "네, 다만 신원이 노출되지 않는다는 전제하에 답변드리겠습니다. 회사 쪽에서 눈치채면 곤란해서요.", en: "Sure, but I'll only answer on the condition that my identity stays hidden. It'll be a problem if the company catches on.", ja: "はい、ただ身元が明かされないという前提でお答えします。会社に気づかれると困るので。", zh: "好的，不过我是在身份不会曝光的前提下回答的。要是被公司发现就麻烦了。", vi: "Vâng, chỉ là tôi sẽ trả lời với điều kiện danh tính không bị lộ ra. Vì nếu công ty phát hiện thì rất rắc rối.", es: "Sí, pero responderé solo con la condición de que mi identidad se mantenga en secreto. Sería un problema si la empresa se entera." },
      { speaker: "기자", kr: "물론입니다. 익명 처리는 저희 쪽에서 철저히 지킵니다. 그럼 회계 조작이 언제부터 시작됐다고 보십니까?", en: "Of course. We're strict about keeping sources anonymous. So when do you think the accounting manipulation began?", ja: "もちろんです。匿名処理は私たちが徹底して守ります。それで、会計操作はいつから始まったとお考えですか?", zh: "当然。匿名处理我们会严格保守。那么，您认为财务造假是从什么时候开始的？", vi: "Đương nhiên rồi ạ. Chúng tôi sẽ giữ bí mật danh tính triệt để. Vậy anh/chị nghĩ việc thao túng kế toán bắt đầu từ khi nào?", es: "Por supuesto. Mantenemos el anonimato de nuestras fuentes de forma estricta. Entonces, ¿desde cuándo cree que empezó la manipulación contable?" },
      { speaker: "제보자", kr: "제가 파악하기로는 작년 4분기부터였고, 매출을 부풀리기 위해 가공 거래를 만든 정황이 있습니다.", en: "As far as I know, it started in the fourth quarter of last year, and there are signs they created fabricated transactions to inflate revenue.", ja: "私が把握している限りでは昨年第4四半期からで、売上を水増しするために架空取引を作った形跡があります。", zh: "据我了解是从去年第四季度开始的，有迹象表明他们为了虚增营收而制造了虚假交易。", vi: "Theo tôi nắm được là từ quý bốn năm ngoái, và có dấu hiệu họ tạo ra các giao dịch giả để thổi phồng doanh thu.", es: "Según lo que sé, empezó en el cuarto trimestre del año pasado, y hay indicios de que crearon transacciones ficticias para inflar los ingresos." },
      { speaker: "기자", kr: "구체적인 증거 자료를 확보하고 계신가요? 보도하려면 뒷받침할 근거가 필요합니다.", en: "Do you have concrete evidence in hand? To report this, we need something to substantiate it.", ja: "具体的な証拠資料はお持ちですか? 報道するには裏付けとなる根拠が必要です。", zh: "您手头有具体的证据材料吗？要报道的话需要有支撑的依据。", vi: "Anh/chị có nắm được tài liệu chứng cứ cụ thể không? Để đưa tin cần có căn cứ hỗ trợ.", es: "¿Tiene pruebas concretas en su poder? Para publicar esto necesitamos algo que lo respalde." },
      { speaker: "제보자", kr: "내부 이메일과 결재 문서 일부를 갖고 있는데, 어떻게 전달해야 안전할지 고민입니다.", en: "I have some internal emails and approval documents, but I'm worried about how to hand them over safely.", ja: "内部メールと決裁文書の一部を持っていますが、どう渡せば安全か悩んでいます。", zh: "我手上有一些内部邮件和审批文件，但在犹豫怎么交给你们才安全。", vi: "Tôi có một phần email nội bộ và tài liệu phê duyệt, nhưng đang băn khoăn nên chuyển như thế nào cho an toàn.", es: "Tengo algunos correos internos y documentos de aprobación, pero no sé cómo entregárselos de forma segura." },
      { speaker: "기자", kr: "암호화된 채널로 보내주시면 저희 쪽에서 출처 보호 절차에 따라 처리하겠습니다.", en: "If you send them through an encrypted channel, we'll handle it according to our source-protection protocol.", ja: "暗号化されたチャンネルで送っていただければ、こちらで出所保護の手続きに従って処理します。", zh: "如果通过加密渠道发送，我们会按照信源保护的程序来处理。", vi: "Nếu anh/chị gửi qua kênh mã hóa, chúng tôi sẽ xử lý theo quy trình bảo vệ nguồn tin.", es: "Si nos los envía por un canal cifrado, los procesaremos siguiendo nuestro protocolo de protección de fuentes." },
      { speaker: "제보자", kr: "알겠습니다. 다만 이게 공개됐을 때 회사가 저를 특정할 가능성도 배제할 수 없어서 신중하게 진행해 주세요.", en: "Understood. But once this is published, there's a chance the company could still identify me, so please proceed carefully.", ja: "分かりました。ただ、これが公開されたときに会社が私を特定する可能性も排除できないので、慎重に進めてください。", zh: "明白了。不过这一旦公开，公司锁定我的可能性也不能排除，请务必谨慎行事。", vi: "Tôi hiểu rồi. Chỉ là khi việc này được công khai, khả năng công ty xác định được tôi cũng không loại trừ, nên mong các anh xử lý thận trọng.", es: "Entendido. Pero no se puede descartar que la empresa logre identificarme una vez que esto se publique, así que procedan con mucho cuidado." },
      { speaker: "기자", kr: "충분히 이해합니다. 보도 전에 초안을 검토하실 기회도 드리겠습니다.", en: "I fully understand. We'll also give you a chance to review the draft before it's published.", ja: "十分理解しています。報道前に草稿を確認していただく機会も設けます。", zh: "我完全理解。报道前也会给您一个审阅初稿的机会。", vi: "Tôi hoàn toàn hiểu điều đó. Chúng tôi cũng sẽ cho anh/chị cơ hội xem lại bản thảo trước khi đăng.", es: "Lo entiendo perfectamente. También le daremos la oportunidad de revisar el borrador antes de publicarlo." },
    ],
  },
  {
    id: "phone-c1y-shared-wall",
    situationKey: "phone",
    level: "C1",
    title: { en: "Mediating a dispute between neighbors over a shared wall", ja: "隣家との塀の紛争を仲裁する", zh: "调解邻里间的隔墙纠纷", vi: "Hòa giải tranh chấp giữa hàng xóm về bức tường chung", es: "Mediar en una disputa entre vecinos por un muro medianero" },
    lines: [
      { speaker: "관리소장", kr: "여보세요, 관리소장입니다. 옆집과 담장 문제로 통화 요청하셨다고 해서 연락드렸습니다.", en: "Hello, this is the building manager. I'm calling because you requested to discuss the wall issue with your neighbor.", ja: "もしもし、管理所長です。隣の家との塀の問題で通話をご要望とのことでご連絡しました。", zh: "喂，我是物业管理处的所长。听说您希望就和邻居的隔墙问题通个话，所以联系您了。", vi: "A lô, tôi là trưởng ban quản lý. Tôi liên hệ vì anh/chị yêu cầu trao đổi về vấn đề bức tường với nhà bên cạnh.", es: "Hola, soy el administrador del edificio. Le llamo porque solicitó hablar sobre el problema del muro con el vecino." },
      { speaker: "주민", kr: "네, 옆집에서 저희 쪽 담장에 균열이 갔다고 공사비를 반씩 부담하자는데 원인이 저희 쪽은 아닌 것 같아서요.", en: "Yes, the neighbor is saying our shared wall cracked and wants us to split the repair cost, but I don't think the cause is on our side.", ja: "はい、隣の家がうちの塀にひびが入ったと言って工事費を半分ずつ負担しようというんですが、原因がうちにあるとは思えなくて。", zh: "是的，邻居说我们这边的墙出现了裂缝，想让我们平摊修理费，但我觉得原因不在我们这边。", vi: "Vâng, nhà bên cạnh nói tường bên chúng tôi bị nứt nên muốn chia đôi chi phí sửa chữa, nhưng tôi không nghĩ nguyên nhân là do bên chúng tôi.", es: "Sí, el vecino dice que se agrietó el muro de nuestro lado y quiere que dividamos el costo de la reparación a partes iguales, pero no creo que la causa esté de nuestro lado." },
      { speaker: "관리소장", kr: "일단 균열의 원인을 정확히 파악하는 게 우선일 것 같습니다. 구조기술사 진단을 받아보시는 건 어떠세요?", en: "I think the first step is pinpointing the exact cause of the crack. How about getting a structural engineer's assessment?", ja: "まずはひびの原因を正確に把握するのが先決だと思います。構造技術士の診断を受けてみるのはどうでしょうか?", zh: "我想首先应该准确查明裂缝的原因。要不要请结构工程师做个鉴定？", vi: "Trước tiên tôi nghĩ nên xác định chính xác nguyên nhân vết nứt đã. Anh/chị có muốn nhờ kỹ sư kết cấu chẩn đoán không ạ?", es: "Creo que lo primero debería ser determinar con precisión la causa de la grieta. ¿Qué le parece si solicita una evaluación de un ingeniero estructural?" },
      { speaker: "주민", kr: "그렇게 하면 비용은 누가 부담하나요? 저희로선 원인도 불분명한데 선뜻 진단비를 내기가 부담스럽습니다.", en: "If we do that, who covers the cost? Since the cause isn't even clear, I'm reluctant to pay for the assessment upfront.", ja: "そうすると費用は誰が負担するんですか? 原因も不明なのに診断費を進んで出すのは負担です。", zh: "那样的话费用由谁承担呢？原因都还不明确，让我们主动出鉴定费有点负担。", vi: "Nếu làm vậy thì ai chịu chi phí ạ? Chúng tôi thấy khó chịu tiền chẩn đoán trước khi nguyên nhân còn chưa rõ.", es: "Si hacemos eso, ¿quién paga el costo? Como ni siquiera está claro el origen del problema, me incomoda pagar la evaluación de entrada." },
      { speaker: "관리소장", kr: "관례상 진단비는 양측이 균등 부담하고, 결과에 따라 수리비 분담 비율을 정하는 방식이 합리적입니다.", en: "Conventionally, the assessment cost is split evenly, and the repair-cost ratio is decided based on the findings—that's the reasonable approach.", ja: "慣例上、診断費は双方が均等に負担して、結果に応じて修理費の分担比率を決める方式が合理的です。", zh: "按惯例，鉴定费由双方均摊，再根据结果决定修理费的分摊比例，这样比较合理。", vi: "Theo thông lệ, chi phí chẩn đoán do hai bên chia đều, sau đó dựa vào kết quả để quyết định tỷ lệ chia sẻ chi phí sửa chữa, cách đó hợp lý hơn.", es: "Por costumbre, lo razonable es que ambas partes se repartan el costo de la evaluación a partes iguales y, según el resultado, se decida la proporción de reparto de la reparación." },
      { speaker: "주민", kr: "옆집이 그 방식에 동의할지 모르겠네요. 이미 저희 잘못이라고 단정 짓고 있어서요.", en: "I'm not sure the neighbor will agree to that approach. They've already concluded it's our fault.", ja: "隣の家がその方式に同意するか分かりません。すでにうちのせいだと決めつけているので。", zh: "不知道邻居会不会同意那种方式，他们已经认定是我们的责任了。", vi: "Không biết nhà bên cạnh có đồng ý cách đó không, vì họ đã mặc định là lỗi của chúng tôi rồi.", es: "No sé si el vecino aceptará ese método. Ya han dado por hecho que la culpa es nuestra." },
      { speaker: "관리소장", kr: "제가 중재자로서 양쪽 다 설득해 보겠습니다. 감정적으로 번지기 전에 객관적인 근거로 풀어야 할 문제니까요.", en: "As the mediator, I'll try to persuade both sides. This needs to be resolved with objective evidence before it turns emotional.", ja: "私が仲裁者として両方を説得してみます。感情的にこじれる前に客観的な根拠で解決すべき問題ですから。", zh: "我会以调解人的身份去说服双方。这本该在演变成情绪化冲突之前，用客观依据来解决的问题。", vi: "Tôi sẽ đóng vai trò trung gian thuyết phục cả hai bên. Vấn đề này nên giải quyết bằng căn cứ khách quan trước khi trở nên căng thẳng cảm xúc.", es: "Como mediador, intentaré convencer a ambas partes. Este es un problema que debe resolverse con evidencia objetiva antes de que se convierta en algo emocional." },
      { speaker: "주민", kr: "네, 그렇게 해 주시면 감사하겠습니다. 저희도 무리한 요구는 아니라고 생각해서요.", en: "Yes, I'd appreciate that. We don't think our position is an unreasonable ask.", ja: "はい、そうしていただけると助かります。私たちも無理な要求ではないと思っていますので。", zh: "好的，那样的话就太感谢了。我们也觉得自己的要求并不过分。", vi: "Vâng, nếu anh làm được vậy thì tôi rất cảm ơn. Chúng tôi cũng nghĩ yêu cầu của mình không phải là quá đáng.", es: "Sí, se lo agradecería mucho. Nosotros tampoco creemos que sea una exigencia desmedida." },
      { speaker: "관리소장", kr: "알겠습니다. 이번 주 안으로 진단 업체 섭외해서 양측에 일정 안내드리겠습니다.", en: "Understood. I'll arrange an inspection company within the week and let both sides know the schedule.", ja: "分かりました。今週中に診断業者を手配して、双方に日程をご案内します。", zh: "明白了。我会在这周之内安排好鉴定机构，并将日程通知双方。", vi: "Tôi hiểu rồi. Trong tuần này tôi sẽ liên hệ đơn vị chẩn đoán và thông báo lịch cho cả hai bên.", es: "Entendido. Dentro de esta semana contrataré a una empresa de evaluación y les avisaré del calendario a ambas partes." },
    ],
  },
  {
    id: "phone-c1y-lawyer-client",
    situationKey: "phone",
    level: "C1",
    title: { en: "A lawyer explains contract terms to a worried client", ja: "弁護士が不安な依頼人に契約条項を説明する", zh: "律师向忧心的客户解释合同条款", vi: "Luật sư giải thích điều khoản hợp đồng cho khách hàng lo lắng", es: "Un abogado explica las cláusulas de un contrato a un cliente preocupado" },
    lines: [
      { speaker: "변호사", kr: "여보세요, 계약서 검토 결과 말씀드리려고 전화드렸습니다. 걱정 많이 하셨죠?", en: "Hello, I'm calling to go over the contract review results. I know you've been worried about this.", ja: "もしもし、契約書の検討結果をお伝えしようとお電話しました。ずいぶんご心配されていましたよね。", zh: "喂，是想跟您说一下合同审查的结果，才打电话过来的。您一直很担心吧。", vi: "A lô, tôi gọi để báo kết quả rà soát hợp đồng. Chắc anh/chị lo lắng nhiều lắm phải không ạ?", es: "Hola, le llamo para comentarle el resultado de la revisión del contrato. Sé que ha estado muy preocupado, ¿verdad?" },
      { speaker: "의뢰인", kr: "네, 특히 위약금 조항이 너무 과하게 잡혀 있는 것 같아서 사인하기 전에 꼭 확인받고 싶었어요.", en: "Yes, especially the penalty clause—it seemed way too steep, so I wanted to check with you before signing.", ja: "はい、特に違約金条項が過剰に設定されているようで、サインする前にどうしても確認していただきたかったんです。", zh: "是的，尤其是违约金条款看起来定得太高了，签字前无论如何都想请您确认一下。", vi: "Vâng, đặc biệt điều khoản phạt vi phạm có vẻ quá cao, nên tôi muốn được xác nhận trước khi ký.", es: "Sí, sobre todo la cláusula de penalización me parece excesiva, así que quería asegurarme con usted antes de firmar." },
      { speaker: "변호사", kr: "말씀하신 대로 계약 해지 시 위약금이 계약금의 세 배로 되어 있는데, 이건 업계 관행보다 상당히 높은 수준입니다.", en: "As you said, the penalty for terminating the contract is set at three times the down payment, which is considerably higher than industry norms.", ja: "おっしゃる通り、契約解除時の違約金が契約金の三倍になっていますが、これは業界慣行よりかなり高い水準です。", zh: "正如您所说，解约时的违约金定为定金的三倍，这比业界惯例要高出不少。", vi: "Đúng như anh/chị nói, khoản phạt khi hủy hợp đồng được đặt gấp ba lần tiền đặt cọc, mức này cao hơn khá nhiều so với thông lệ ngành.", es: "Como dice, la penalización por rescisión del contrato equivale a tres veces el depósito, lo cual está bastante por encima de lo habitual en el sector." },
      { speaker: "의뢰인", kr: "그럼 이 조항을 조정해 달라고 요구할 수 있는 건가요? 상대 쪽에서 순순히 받아들일지 모르겠네요.", en: "So can I request that this clause be adjusted? I'm not sure the other party will readily accept it though.", ja: "それではこの条項の調整を要求できるということですか? 相手側が素直に受け入れるか分かりませんが。", zh: "那这样的话可以要求调整这个条款吗？不过我不确定对方会不会痛快接受。", vi: "Vậy tôi có thể yêu cầu điều chỉnh điều khoản này không ạ? Không biết bên kia có dễ dàng chấp nhận không.", es: "Entonces, ¿puedo exigir que se ajuste esta cláusula? No sé si la otra parte lo aceptará sin más." },
      { speaker: "변호사", kr: "협상의 여지는 충분합니다. 다만 무리하게 밀어붙이기보다는 위약금 상한선을 두는 절충안을 제안하시는 게 좋겠습니다.", en: "There's plenty of room for negotiation. Rather than pushing too hard, though, I'd suggest proposing a compromise that caps the penalty amount.", ja: "交渉の余地は十分にあります。ただ、無理に押し切るよりは違約金の上限を設ける折衷案を提案する方がいいでしょう。", zh: "谈判的余地是很充分的。不过，比起强行推进，建议提出一个设定违约金上限的折中方案会更好。", vi: "Có đủ khả năng đàm phán. Chỉ là thay vì ép quá mạnh, nên đề xuất phương án dung hòa là đặt mức trần cho khoản phạt.", es: "Hay bastante margen para negociar. Sin embargo, en lugar de forzar demasiado, sería mejor proponer una solución intermedia que fije un límite máximo a la penalización." },
      { speaker: "의뢰인", kr: "알겠습니다. 그리고 계약 기간 자동 연장 조항도 애매하게 쓰여 있던데, 그것도 문제가 될까요?", en: "Understood. Also, the automatic renewal clause was written pretty vaguely—could that be an issue too?", ja: "分かりました。それと契約期間の自動延長条項も曖昧に書かれていましたが、それも問題になりますか?", zh: "明白了。还有合同期限自动延长的条款写得也很含糊，那部分也会有问题吗？", vi: "Tôi hiểu rồi. Và điều khoản tự động gia hạn hợp đồng cũng viết mập mờ, cái đó có thành vấn đề không ạ?", es: "Entendido. Además, la cláusula de renovación automática del contrato también estaba redactada de forma bastante ambigua, ¿eso también podría ser un problema?" },
      { speaker: "변호사", kr: "네, 해지 통보 기한이 명시되어 있지 않아서 자칫하면 원치 않는 기간까지 묶일 수 있습니다. 이 부분도 반드시 손봐야 합니다.", en: "Yes, since there's no specified deadline for termination notice, you could end up locked in longer than you want. This needs to be revised as well.", ja: "はい、解約通知の期限が明記されていないので、思わぬ長期間拘束される可能性があります。この部分も必ず修正すべきです。", zh: "是的，因为没有写明解约通知的期限，很可能会被绑定超出您预期的期限。这部分也一定要修改。", vi: "Vâng, vì không ghi rõ thời hạn thông báo hủy nên có thể vô tình bị ràng buộc lâu hơn mong muốn. Phần này cũng nhất định phải sửa.", es: "Sí, como no se especifica el plazo de aviso para rescindir, podría quedar atado durante más tiempo del que desea sin darse cuenta. Esta parte también hay que corregirla sin falta." },
      { speaker: "의뢰인", kr: "생각보다 손볼 부분이 많네요. 수정 요청서는 언제쯤 받아볼 수 있을까요?", en: "There's more to fix than I expected. When can I get the revision request document?", ja: "思ったより直すべき部分が多いですね。修正要求書はいつ頃受け取れますか?", zh: "要修改的地方比想象中多啊。修改申请书大概什么时候能拿到？", vi: "Có nhiều chỗ cần sửa hơn tôi tưởng. Khi nào tôi nhận được yêu cầu sửa đổi ạ?", es: "Hay más cosas que corregir de lo que pensaba. ¿Cuándo podría recibir la solicitud de modificación?" },
      { speaker: "변호사", kr: "오늘 중으로 초안을 정리해서 메일로 보내드리겠습니다. 서명은 그 이후에 진행하시죠.", en: "I'll draft it up and send it by email today. Let's hold off on signing until after that.", ja: "本日中に草稿をまとめてメールでお送りします。サインはそれ以降にしましょう。", zh: "今天之内我会整理好草案发邮件给您。签字请等那之后再进行。", vi: "Tôi sẽ soạn bản dự thảo và gửi qua email trong hôm nay. Việc ký chỉ nên tiến hành sau đó.", es: "Prepararé el borrador hoy mismo y se lo enviaré por correo. Dejemos la firma para después de eso." },
    ],
  },
  {
    id: "phone-c1y-parent-care",
    situationKey: "phone",
    level: "C1",
    title: { en: "Discussing end-of-life care arrangements with a parent", ja: "親と終末期ケアの手配について話し合う", zh: "与母亲商量临终照护安排", vi: "Bàn với mẹ về sắp xếp chăm sóc cuối đời", es: "Hablar con la madre sobre los cuidados al final de la vida" },
    lines: [
      { speaker: "딸", kr: "엄마, 저번에 병원에서 말씀하신 요양 시설 문제로 다시 전화했어요. 좀 더 자세히 얘기해 보고 싶어서요.", en: "Mom, I'm calling again about the care facility the hospital mentioned last time. I wanted to talk it through in more detail.", ja: "お母さん、この前病院で言われた療養施設のことでまた電話したの。もう少し詳しく話したくて。", zh: "妈，是关于上次医院提到的疗养设施的事再打电话给你的，想再详细聊聊。", vi: "Mẹ ơi, con gọi lại về việc cơ sở dưỡng lão mà bác sĩ nói lần trước. Con muốn bàn kỹ hơn một chút.", es: "Mamá, te llamo otra vez por el tema de la residencia que mencionó el médico la última vez. Quería hablarlo con más detalle." },
      { speaker: "어머니", kr: "그래, 근데 엄마는 솔직히 집에서 지내고 싶은 마음이 커. 시설에 들어가는 건 아직 마음의 준비가 안 됐어.", en: "Sure, but honestly, I really want to stay at home. I'm not mentally ready to go into a facility yet.", ja: "そう、でもお母さんは正直、家で過ごしたい気持ちが強いのよ。施設に入るのはまだ心の準備ができてないの。", zh: "是啊，不过妈妈说实话，很想留在家里，还没做好去疗养院的心理准备。", vi: "Ừ, nhưng thật lòng mẹ rất muốn ở nhà. Vào cơ sở dưỡng lão thì mẹ chưa chuẩn bị tinh thần được.", es: "Vale, pero la verdad es que tengo muchas ganas de quedarme en casa. Aún no estoy preparada mentalmente para entrar en una residencia." },
      { speaker: "딸", kr: "그 마음 이해해요. 그런데 지금처럼 저희가 자주 못 들여다보는 상황에서는 재택 간병인을 두는 게 어떨까 싶어요.", en: "I understand how you feel. But given that we can't check in often these days, what about having an in-home caregiver instead?", ja: "その気持ちは分かる。でも今みたいに頻繁に見に行けない状況だと、在宅の介護人を置くのはどうかなと思って。", zh: "我理解你的心情。不过现在这种情况我们没法经常去看你，我在想是不是可以请个上门护理人员。", vi: "Con hiểu cảm giác đó của mẹ. Nhưng trong tình huống như hiện tại, tụi con không thể ghé thăm thường xuyên, con nghĩ nên thuê người chăm sóc tại nhà thì sao ạ.", es: "Entiendo cómo te sientes. Pero dado que ahora no podemos visitarte con frecuencia, ¿qué te parece contratar a un cuidador a domicilio?" },
      { speaker: "어머니", kr: "간병인이라... 낯선 사람이 집에 드나드는 게 부담스럽긴 한데, 시설보다는 나을 것 같기도 하고.", en: "A caregiver... having a stranger come in and out of the house feels burdensome, but it might be better than a facility.", ja: "介護人か… 見知らぬ人が家に出入りするのは気が引けるけど、施設よりはましかもね。", zh: "护理人员啊……陌生人进出家里让人有点为难，不过可能比去疗养院好一些。", vi: "Người chăm sóc à... người lạ ra vào nhà thì hơi ngại, nhưng có lẽ vẫn tốt hơn vào cơ sở dưỡng lão.", es: "Un cuidador... me incomoda que entre y salga de casa una persona desconocida, pero tal vez sea mejor que una residencia." },
      { speaker: "딸", kr: "제가 알아보니까 방문 간호 서비스랑 주간 보호센터를 병행하는 방법도 있더라고요. 비용 지원도 일부 받을 수 있고요.", en: "From what I looked into, there's also an option to combine home nursing visits with a day-care center. Some of the cost can be subsidized too.", ja: "私が調べたら、訪問看護サービスとデイケアセンターを併用する方法もあったの。費用も一部支援してもらえるみたい。", zh: "我查了一下，也有把上门护理服务和日间照护中心结合起来用的方法，费用还能部分申请补贴。", vi: "Con tìm hiểu thì cũng có cách kết hợp dịch vụ điều dưỡng tại nhà với trung tâm chăm sóc ban ngày. Còn được hỗ trợ một phần chi phí nữa.", es: "He investigado y también existe la opción de combinar visitas de enfermería a domicilio con un centro de día. Además, se puede recibir ayuda parcial para el costo." },
      { speaker: "어머니", kr: "그건 좀 솔깃하네. 근데 의료진 판단은 어떻대? 혼자 지내는 게 무리라고 하시던데.", en: "That sounds a bit more appealing. But what did the medical staff say? They mentioned it might be too much to live alone.", ja: "それはちょっと惹かれるわね。でも医師の判断はどうなの? 一人で暮らすのは無理だって言ってたけど。", zh: "那个还挺吸引人的。不过医生怎么说的？他们说一个人生活有点吃力吧。", vi: "Nghe cũng hấp dẫn đấy. Nhưng bác sĩ đánh giá thế nào? Họ nói sống một mình thì hơi quá sức mà.", es: "Eso me atrae un poco más. Pero ¿qué opina el equipo médico? Dijeron que vivir sola sería demasiado." },
      { speaker: "딸", kr: "네, 담당의 선생님도 최소한 낮 시간대는 돌봄이 필요하다고 하셨어요. 그래서 절충안으로 이 방법을 제안드리는 거예요.", en: "Right, the attending doctor also said you need care at least during daytime hours. That's why I'm suggesting this as a middle ground.", ja: "うん、主治医の先生も少なくとも昼間の時間帯はケアが必要だとおっしゃってた。だから折衷案としてこの方法を提案しているの。", zh: "嗯，主治医生也说至少白天的时间需要有人照顾。所以我才提议这个作为折中方案。", vi: "Vâng, bác sĩ điều trị cũng nói ít nhất ban ngày cần có người chăm sóc. Vì vậy con mới đề xuất cách này như một phương án dung hòa.", es: "Sí, el médico también dijo que necesitas cuidados al menos durante el día. Por eso te propongo esto como una solución intermedia." },
      { speaker: "어머니", kr: "알겠어. 일단 방문 간호 상담부터 받아보고 결정하자. 급하게 결론 내리고 싶진 않아.", en: "All right. Let's start with a home-nursing consultation before deciding. I don't want to rush into a conclusion.", ja: "分かった。とりあえず訪問看護の相談から受けて決めましょう。急いで結論を出したくないの。", zh: "好吧。那先去做个上门护理的咨询再决定吧，我不想急着下结论。", vi: "Được rồi. Trước tiên cứ tư vấn điều dưỡng tại nhà rồi quyết định sau. Mẹ không muốn vội vàng kết luận.", es: "De acuerdo. Primero recibamos la consulta de enfermería a domicilio y decidamos después. No quiero llegar a una conclusión con prisa." },
      { speaker: "딸", kr: "그럼요, 천천히 알아봐요. 다음 주에 상담 예약 잡아서 같이 가 볼게요.", en: "Of course, let's take our time. I'll book a consultation appointment for next week and go with you.", ja: "もちろん、ゆっくり調べましょう。来週相談の予約を取って一緒に行くね。", zh: "当然，我们慢慢来。我下周去预约咨询，然后陪你一起去。", vi: "Đương nhiên rồi mẹ, mình cứ từ từ tìm hiểu. Tuần sau con sẽ đặt lịch tư vấn và đi cùng mẹ.", es: "Claro que sí, mamá, vayamos con calma. La semana que viene reservaré una cita para la consulta e iré contigo." },
      { speaker: "어머니", kr: "고마워, 딸. 혼자 결정 안 하고 이렇게 물어봐 줘서 마음이 놓이네.", en: "Thank you, sweetheart. It's a relief that you're asking me instead of deciding on your own.", ja: "ありがとう、娘。一人で決めずにこうやって聞いてくれて安心するわ。", zh: "谢谢你，闺女。你没有自己一个人做决定，而是这样来问我，我很安心。", vi: "Cảm ơn con gái. Con không tự quyết một mình mà hỏi ý mẹ như vậy làm mẹ thấy yên tâm hơn nhiều.", es: "Gracias, hija. Me tranquiliza que me preguntes en vez de decidir tú sola." },
    ],
  },
  {
    id: "phone-c1y-investor-pitch",
    situationKey: "phone",
    level: "C1",
    title: { en: "A startup founder pitches an investor over the phone", ja: "スタートアップ創業者が電話で投資家にピッチする", zh: "创业者电话向投资人推介项目", vi: "Người sáng lập startup gọi điện thuyết trình cho nhà đầu tư", es: "Un fundador de startup presenta su proyecto a un inversor por teléfono" },
    lines: [
      { speaker: "창업자", kr: "안녕하세요, 지난주 소개받고 연락드린 스타트업 대표입니다. 저희 서비스에 관심 가져 주셔서 감사합니다.", en: "Hello, I'm the founder who was introduced to you last week. Thank you for showing interest in our service.", ja: "こんにちは、先週ご紹介いただいてご連絡したスタートアップの代表です。私どものサービスにご関心をお持ちいただきありがとうございます。", zh: "您好，我是上周经人介绍联系您的初创公司创始人。感谢您对我们服务的关注。", vi: "Xin chào, tôi là đại diện công ty khởi nghiệp được giới thiệu tuần trước. Cảm ơn anh đã quan tâm đến dịch vụ của chúng tôi.", es: "Hola, soy el fundador que le presentaron la semana pasada. Gracias por interesarse en nuestro servicio." },
      { speaker: "투자자", kr: "네, 반갑습니다. 자료는 훑어봤는데, 매출보다 사용자 성장에 더 방점을 두고 계신 것 같더라고요. 이유가 있나요?", en: "Nice to meet you. I skimmed the materials, and it looks like you're putting more weight on user growth than revenue. Is there a reason for that?", ja: "はい、初めまして。資料はざっと拝見しましたが、売上よりユーザー成長の方に重点を置かれているようですね。理由はありますか?", zh: "您好，初次见面。资料我大致看过了，感觉您把重点放在用户增长上而不是营收上，这有什么原因吗？", vi: "Vâng, rất vui được biết anh. Tôi đã xem qua tài liệu, có vẻ anh chú trọng vào tăng trưởng người dùng hơn là doanh thu. Có lý do gì không ạ?", es: "Sí, encantado. Eché un vistazo al material, y parece que le dan más peso al crecimiento de usuarios que a los ingresos. ¿Hay alguna razón?" },
      { speaker: "창업자", kr: "네, 저희는 초기 단계에서 록인 효과를 만드는 게 우선이라고 판단했습니다. 유료 전환은 3분기부터 본격화할 계획입니다.", en: "Yes, we judged that creating a lock-in effect was the priority at this early stage. We plan to fully roll out monetization starting Q3.", ja: "はい、私たちは初期段階ではロックイン効果を作ることが優先だと判断しました。有料転換は第3四半期から本格化する計画です。", zh: "是的，我们判断在早期阶段建立锁定效应是首要任务。付费转化计划从第三季度开始全面推进。", vi: "Vâng, chúng tôi đánh giá rằng ở giai đoạn đầu, việc tạo hiệu ứng khóa chân người dùng là ưu tiên hàng đầu. Kế hoạch chuyển đổi trả phí sẽ triển khai mạnh từ quý ba.", es: "Sí, consideramos que en esta etapa inicial la prioridad era generar un efecto de fidelización. Planeamos impulsar la monetización a partir del tercer trimestre." },
      { speaker: "투자자", kr: "그렇군요. 그런데 경쟁사도 비슷한 전략을 쓰고 있던데, 저희 쪽에서는 차별화 지점이 뭔지가 궁금하네요.", en: "I see. But competitors seem to be using a similar strategy, so I'm curious what your differentiator is from our perspective.", ja: "なるほど。ただ競合他社も似たような戦略を使っているようですが、御社の差別化ポイントは何なのか気になりますね。", zh: "原来如此。不过竞争对手似乎也在用类似的策略，我很好奇贵公司的差异化点在哪里。", vi: "Tôi hiểu rồi. Nhưng đối thủ cạnh tranh cũng đang dùng chiến lược tương tự, tôi tò mò điểm khác biệt của các anh là gì.", es: "Ya veo. Pero los competidores parecen usar una estrategia similar, así que me pregunto cuál es su factor diferenciador." },
      { speaker: "창업자", kr: "저희는 데이터 기반 추천 알고리즘의 정확도에서 우위를 갖고 있고, 실제로 재방문율이 업계 평균 대비 두 배 이상입니다.", en: "We have an edge in the accuracy of our data-driven recommendation algorithm, and our return-visit rate is actually more than double the industry average.", ja: "私たちはデータに基づくレコメンドアルゴリズムの精度で優位性を持っていて、実際にリピート率が業界平均の二倍以上です。", zh: "我们在基于数据的推荐算法精度上具有优势，实际的复访率是业界平均水平的两倍以上。", vi: "Chúng tôi có ưu thế về độ chính xác của thuật toán gợi ý dựa trên dữ liệu, và tỷ lệ quay lại thực tế cao gấp đôi mức trung bình ngành.", es: "Tenemos ventaja en la precisión de nuestro algoritmo de recomendación basado en datos, y de hecho nuestra tasa de retorno de usuarios duplica el promedio del sector." },
      { speaker: "투자자", kr: "수치가 인상적이긴 하네요. 다만 이번 라운드 밸류에이션이 다소 높게 책정된 것 같은데, 근거를 더 설명해 주실 수 있나요?", en: "Those numbers are impressive. Still, this round's valuation seems set a bit high—can you explain the rationale further?", ja: "数字は印象的ですね。ただ今回のラウンドの評価額が少し高めに設定されている気がしますが、根拠をもう少し説明していただけますか?", zh: "数字确实令人印象深刻。不过这轮的估值感觉定得偏高，能再解释一下依据吗？", vi: "Con số này khá ấn tượng đấy. Chỉ là định giá vòng gọi vốn lần này có vẻ hơi cao, anh có thể giải thích thêm căn cứ không ạ?", es: "Las cifras son impresionantes. Aun así, la valoración de esta ronda me parece algo elevada; ¿podría explicarme mejor la justificación?" },
      { speaker: "창업자", kr: "성장률과 시장 규모를 반영한 결과인데, 조정 여지는 있습니다. 실사 과정에서 구체적으로 논의드리고 싶습니다.", en: "It reflects our growth rate and market size, but there's room for adjustment. I'd like to discuss the specifics during due diligence.", ja: "成長率と市場規模を反映した結果ですが、調整の余地はあります。デューデリジェンスの過程で具体的にお話ししたいです。", zh: "这是反映了增长率和市场规模的结果，但有调整的余地。我想在尽职调查的过程中具体讨论一下。", vi: "Đó là kết quả phản ánh tốc độ tăng trưởng và quy mô thị trường, nhưng vẫn có thể điều chỉnh. Tôi muốn thảo luận cụ thể hơn trong quá trình thẩm định.", es: "Refleja nuestra tasa de crecimiento y el tamaño del mercado, pero hay margen de ajuste. Me gustaría discutirlo en detalle durante la due diligence." },
      { speaker: "투자자", kr: "좋습니다. 그럼 다음 주에 실사팀과 미팅 잡아서 재무 데이터 자세히 검토해 보죠.", en: "Good. Let's schedule a meeting with the due-diligence team next week and go over the financial data in detail.", ja: "結構です。それでは来週デューデリジェンスチームとミーティングを組んで財務データを詳しく検討してみましょう。", zh: "好的。那我们下周和尽职调查团队安排一次会议，详细审查一下财务数据吧。", vi: "Được. Vậy tuần sau ta sắp xếp buổi họp với đội thẩm định để xem kỹ dữ liệu tài chính nhé.", es: "Muy bien. Entonces concertemos una reunión con el equipo de due diligence la semana que viene y revisemos los datos financieros con detalle." },
      { speaker: "창업자", kr: "네, 필요한 자료는 미리 정리해서 보내드리겠습니다. 좋은 결과로 이어지길 바랍니다.", en: "Sure, I'll prepare and send the necessary materials in advance. I hope this leads to a good outcome.", ja: "はい、必要な資料は事前にまとめてお送りします。良い結果につながることを願っています。", zh: "好的，我会提前整理好所需资料发给您。希望这能带来一个好结果。", vi: "Vâng, tôi sẽ chuẩn bị sẵn tài liệu cần thiết và gửi trước. Mong sẽ có kết quả tốt đẹp.", es: "Sí, prepararé de antemano el material necesario y se lo enviaré. Espero que esto lleve a un buen resultado." },
    ],
  },
  {
    id: "phone-c1y-union-negotiation",
    situationKey: "phone",
    level: "C1",
    title: { en: "A union rep negotiates with management", ja: "労組代表が経営陣と交渉する", zh: "工会代表与管理层谈判", vi: "Đại diện công đoàn đàm phán với ban quản lý", es: "Un representante sindical negocia con la dirección" },
    lines: [
      { speaker: "노조 대표", kr: "여보세요, 이번 임금 협상 관련해서 실무진 입장을 먼저 들어보고 싶어서 전화드렸습니다.", en: "Hello, I'm calling to hear management's position first regarding this round of wage negotiations.", ja: "もしもし、今回の賃金交渉に関して、まず実務陣の立場をお聞きしたくてお電話しました。", zh: "喂，是想先听听管理层这边的立场，所以就这次工资谈判打电话过来了。", vi: "A lô, tôi gọi để nghe trước lập trường của phía thực thi về đợt thương lượng lương lần này.", es: "Hola, le llamo para escuchar primero la postura de la dirección sobre esta ronda de negociación salarial." },
      { speaker: "인사담당", kr: "네, 저희 쪽에서는 물가 상승률을 고려해 3퍼센트 인상안을 검토하고 있습니다. 노조 측 요구안과는 차이가 있죠.", en: "Yes, on our end we're considering a 3 percent raise reflecting inflation. That's some distance from the union's proposal, I know.", ja: "はい、こちらとしては物価上昇率を考慮して3パーセントの引き上げ案を検討しています。組合側の要求案とは差がありますね。", zh: "好的，我们这边正在考虑参考物价上涨率，提出百分之三的涨幅方案。这和工会那边的要求确实有差距。", vi: "Vâng, phía chúng tôi đang xem xét mức tăng ba phần trăm dựa trên tỷ lệ lạm phát. Tôi biết là có khoảng cách với yêu cầu của công đoàn.", es: "Sí, por nuestra parte estamos evaluando un aumento del 3 por ciento teniendo en cuenta la inflación. Sé que hay una distancia con la propuesta del sindicato." },
      { speaker: "노조 대표", kr: "저희는 5퍼센트를 제시했는데, 3퍼센트로는 실질 임금이 오히려 하락하는 셈이라 조합원들이 받아들이기 어렵습니다.", en: "We proposed 5 percent. At 3 percent, real wages would actually fall, so it's hard for our members to accept.", ja: "私たちは5パーセントを提示したのですが、3パーセントでは実質賃金がむしろ下がることになるので、組合員が受け入れるのは難しいです。", zh: "我们提出的是百分之五，如果是百分之三，实际工资反而会下降，工会成员很难接受。", vi: "Chúng tôi đề xuất năm phần trăm, nếu chỉ ba phần trăm thì lương thực tế lại giảm đi, các đoàn viên khó chấp nhận được.", es: "Nosotros propusimos un 5 por ciento; con un 3 por ciento el salario real en realidad bajaría, así que es difícil que los afiliados lo acepten." },
      { speaker: "인사담당", kr: "회사 사정도 이해해 주셨으면 합니다. 올해 실적이 예상보다 저조해서 인건비 부담이 만만치 않은 상황입니다.", en: "I hope you can understand the company's situation too. Performance this year has been lower than expected, so the labor-cost burden is significant.", ja: "会社の事情もご理解いただければと思います。今年の実績が予想より振るわず、人件費の負担が軽くない状況です。", zh: "也希望您能理解一下公司的处境，今年的业绩不如预期，人力成本负担并不轻。", vi: "Mong anh cũng hiểu cho tình hình công ty. Kết quả kinh doanh năm nay thấp hơn dự kiến nên gánh nặng chi phí nhân công không hề nhỏ.", es: "Espero que también comprendan la situación de la empresa. Los resultados de este año han sido más bajos de lo esperado, y la carga de costos laborales no es menor." },
      { speaker: "노조 대표", kr: "그 부분은 이해합니다만, 대신 성과급이나 복지 포인트 확대 같은 대안이라도 마련해 주셔야 조합원 설득이 가능합니다.", en: "I understand that part, but you'll need to provide alternatives—like performance bonuses or expanded benefit points—for me to persuade our members.", ja: "その部分は理解します。ただ代わりに成果給や福利ポイントの拡大のような代案を用意していただかないと、組合員の説得ができません。", zh: "那部分我理解。不过如果不准备一些替代方案，比如绩效奖金或扩大福利积分，我很难说服工会成员。", vi: "Phần đó tôi hiểu, nhưng phải có thêm phương án thay thế như thưởng theo hiệu suất hay mở rộng điểm phúc lợi thì tôi mới thuyết phục được đoàn viên.", es: "Entiendo esa parte, pero necesitan ofrecer alternativas, como bonos por desempeño o ampliar los puntos de beneficios sociales, para que pueda convencer a los afiliados." },
      { speaker: "인사담당", kr: "일리 있는 제안이네요. 기본급 인상률은 4퍼센트로 조정하고, 복지 포인트를 상향하는 안을 검토해 보겠습니다.", en: "That's a reasonable proposal. We'll consider adjusting the base pay increase to 4 percent and raising the benefit points.", ja: "もっともな提案ですね。基本給の引き上げ率は4パーセントに調整し、福利ポイントを引き上げる案を検討してみます。", zh: "这是合理的提议。我们会考虑把基本工资涨幅调整到百分之四，并提高福利积分。", vi: "Đó là đề xuất hợp lý. Chúng tôi sẽ xem xét điều chỉnh mức tăng lương cơ bản lên bốn phần trăm và nâng điểm phúc lợi.", es: "Es una propuesta razonable. Consideraremos ajustar el aumento del salario base al 4 por ciento y elevar los puntos de beneficios." },
      { speaker: "노조 대표", kr: "긍정적으로 검토해 주셔서 감사합니다. 다만 이건 잠정안이니 조합원 총회 거쳐서 다시 연락드리겠습니다.", en: "Thank you for considering it positively. But this is only a tentative proposal, so I'll follow up after it goes through the union general meeting.", ja: "前向きにご検討いただきありがとうございます。ただこれは暫定案なので、組合員総会を経てまたご連絡します。", zh: "感谢您积极考虑。不过这只是一个暂定方案，我会在工会成员大会通过后再联系您。", vi: "Cảm ơn anh đã xem xét tích cực. Chỉ là đây mới là phương án tạm thời, tôi sẽ liên hệ lại sau khi họp đại hội đoàn viên.", es: "Le agradezco que lo considere de forma favorable. Pero esto es solo una propuesta provisional, así que me pondré en contacto de nuevo después de la asamblea general del sindicato." },
      { speaker: "인사담당", kr: "네, 총회 일정 정해지면 미리 알려주세요. 저희도 준비해서 성실히 임하겠습니다.", en: "Sure, please let us know once the meeting date is set. We'll prepare and engage in good faith as well.", ja: "はい、総会の日程が決まったら事前にお知らせください。こちらも準備して誠実に臨みます。", zh: "好的，大会日程定下来后请提前通知我们，我们这边也会做好准备，诚意应对。", vi: "Vâng, khi có lịch đại hội xin báo trước cho chúng tôi. Chúng tôi cũng sẽ chuẩn bị và tham gia nghiêm túc.", es: "Claro, avísenos con antelación en cuanto se fije la fecha de la asamblea. Nosotros también nos prepararemos y participaremos con seriedad." },
    ],
  },
  {
    id: "phone-c1y-credit-dispute",
    situationKey: "phone",
    level: "C1",
    title: { en: "Disputing a credit report error", ja: "信用情報の誤りに異議を申し立てる", zh: "对信用报告的错误提出异议", vi: "Khiếu nại lỗi trong báo cáo tín dụng", es: "Disputar un error en un informe crediticio" },
    lines: [
      { speaker: "상담원", kr: "여보세요, 신용정보원입니다. 신용 등급 관련 이의 신청 접수하신 건으로 연락드렸습니다.", en: "Hello, this is the credit bureau. I'm calling regarding the dispute you filed about your credit rating.", ja: "もしもし、信用情報院です。信用等級に関する異議申請の件でご連絡しました。", zh: "喂，这里是信用信息院，是就您提交的信用评级异议申请给您回电的。", vi: "A lô, đây là trung tâm thông tin tín dụng. Tôi gọi về đơn khiếu nại liên quan đến hạng tín dụng của anh/chị.", es: "Hola, aquí la central de información crediticia. Le llamamos por la solicitud de reclamación que presentó sobre su calificación crediticia." },
      { speaker: "고객", kr: "네, 몇 년 전에 완납한 대출이 아직도 연체 이력으로 남아 있어서 등급에 영향을 주고 있더라고요.", en: "Yes, a loan I fully paid off years ago is still showing up as a delinquency and it's affecting my rating.", ja: "はい、数年前に完済したローンがまだ延滞履歴として残っていて、等級に影響を与えているようなんです。", zh: "是的，好几年前就已经还清的贷款，现在还留着逾期记录，好像影响到了我的信用等级。", vi: "Vâng, khoản vay tôi đã trả hết mấy năm trước mà vẫn còn nằm trong lịch sử nợ quá hạn, ảnh hưởng đến hạng tín dụng của tôi.", es: "Sí, hay un préstamo que pagué por completo hace varios años y todavía figura como historial de mora, lo cual está afectando mi calificación." },
      { speaker: "상담원", kr: "확인해 보니 해당 금융사에서 상환 완료 처리를 늦게 통보한 것으로 나오네요. 관련 서류는 갖고 계신가요?", en: "Looking into it, it seems the financial institution reported the payoff late. Do you have the relevant documents?", ja: "確認したところ、該当金融機関が償還完了処理を遅く通知したことが分かりました。関連書類はお持ちですか?", zh: "查了一下，是相关金融机构完成还款处理后通知得比较晚。您手上有相关文件吗？", vi: "Kiểm tra thì có vẻ tổ chức tài chính liên quan đã báo cáo việc hoàn tất trả nợ chậm. Anh/chị có giữ giấy tờ liên quan không ạ?", es: "Al revisarlo, parece que la entidad financiera notificó tarde la finalización del pago. ¿Tiene los documentos correspondientes?" },
      { speaker: "고객", kr: "네, 완제 증명서는 갖고 있는데, 이걸 어디로 제출해야 정정이 빠르게 처리될까요?", en: "Yes, I have the payoff certificate. Where should I submit it for the correction to be processed quickly?", ja: "はい、完済証明書は持っていますが、これをどこに提出すれば訂正が早く処理されますか?", zh: "有的，我手上有还清证明，这个提交到哪里能让更正处理得更快呢？", vi: "Có ạ, tôi có giấy chứng nhận trả hết nợ, tôi nên nộp ở đâu để xử lý điều chỉnh nhanh nhất ạ?", es: "Sí, tengo el certificado de liquidación total, ¿dónde debería presentarlo para que la corrección se procese rápido?" },
      { speaker: "상담원", kr: "저희 쪽 온라인 민원 창구에 스캔본을 첨부해서 접수해 주시면, 영업일 기준 5일 이내에 정정 처리됩니다.", en: "If you attach a scanned copy through our online complaint portal, the correction will be processed within five business days.", ja: "こちらのオンライン苦情窓口にスキャンしたものを添付して申請していただければ、営業日基準で5日以内に訂正処理されます。", zh: "只要在我们的在线投诉窗口上传扫描件提交申请，按工作日计算五天之内就会完成更正处理。", vi: "Nếu anh/chị đính kèm bản scan qua cổng khiếu nại trực tuyến của chúng tôi, việc điều chỉnh sẽ được xử lý trong vòng 5 ngày làm việc.", es: "Si adjunta el escaneo en nuestra ventanilla de reclamaciones en línea, la corrección se procesará en un plazo de 5 días hábiles." },
      { speaker: "고객", kr: "그런데 이 오류 때문에 최근에 대출 심사가 거절됐거든요. 소급해서 피해 보상 같은 것도 가능한가요?", en: "But because of this error, my recent loan application was rejected. Is retroactive compensation for the damage possible?", ja: "ところがこのエラーのせいで最近ローン審査が却下されたんです。遡って被害補償みたいなことは可能ですか?", zh: "可是因为这个错误，我最近的贷款申请被拒了。能不能追溯进行损害赔偿之类的处理？", vi: "Nhưng vì lỗi này mà gần đây tôi bị từ chối xét duyệt vay. Có thể được bồi thường thiệt hại hồi tố không ạ?", es: "Pero por este error me rechazaron una solicitud de préstamo recientemente. ¿Es posible algún tipo de compensación retroactiva por el perjuicio?" },
      { speaker: "상담원", kr: "직접적인 금전 보상은 저희 소관이 아니지만, 정정 확인서를 발급해 드려서 재심사 시 참고 자료로 활용하실 수 있습니다.", en: "Direct monetary compensation isn't within our authority, but we can issue a correction confirmation you can use as supporting material when reapplying.", ja: "直接的な金銭補償は私どもの管轄ではありませんが、訂正確認書を発行して再審査の際の参考資料として活用していただけます。", zh: "直接的金钱赔偿不在我们的职责范围内，但我们可以出具更正确认书，供您在重新申请审核时作为参考资料使用。", vi: "Bồi thường tiền trực tiếp không thuộc thẩm quyền của chúng tôi, nhưng chúng tôi có thể cấp giấy xác nhận điều chỉnh để anh/chị sử dụng làm tài liệu tham khảo khi xét duyệt lại.", es: "La compensación monetaria directa no es competencia nuestra, pero podemos emitirle un certificado de corrección que puede usar como material de referencia al volver a solicitar el préstamo." },
      { speaker: "고객", kr: "알겠습니다. 우선 정정부터 빨리 처리해 주시고, 확인서도 함께 부탁드릴게요.", en: "Understood. Please process the correction quickly first, and include the confirmation document as well.", ja: "分かりました。まず訂正を早く処理していただいて、確認書も一緒にお願いします。", zh: "明白了。请先尽快处理更正，也请一并出具确认书。", vi: "Tôi hiểu rồi. Trước tiên xin xử lý nhanh việc điều chỉnh, và cũng xin cấp luôn giấy xác nhận.", es: "Entendido. Primero procesen la corrección lo antes posible, y también les pido el certificado." },
      { speaker: "상담원", kr: "네, 접수해 주시면 처리 즉시 문자로 안내드리겠습니다. 불편 드려 죄송합니다.", en: "Sure, once you submit it, we'll notify you by text as soon as it's processed. We apologize for the inconvenience.", ja: "はい、申請していただければ処理完了後すぐにショートメッセージでご案内します。ご不便をおかけして申し訳ございません。", zh: "好的，您提交申请后，处理完成会立刻发短信通知您。给您带来不便，我们深表歉意。", vi: "Vâng, sau khi anh/chị nộp đơn, chúng tôi sẽ nhắn tin thông báo ngay khi xử lý xong. Chúng tôi xin lỗi vì sự bất tiện này.", es: "Claro, en cuanto lo presente le avisaremos por mensaje de texto tan pronto se procese. Lamentamos las molestias." },
    ],
  },
  {
    id: "phone-c1y-therapy-intake",
    situationKey: "phone",
    level: "C1",
    title: { en: "A therapist conducts an intake call", ja: "セラピストがインテーク面談の電話を行う", zh: "治疗师进行初诊电话访谈", vi: "Nhà trị liệu thực hiện cuộc gọi tiếp nhận ban đầu", es: "Un terapeuta realiza una entrevista inicial por teléfono" },
    lines: [
      { speaker: "상담사", kr: "여보세요, 상담 예약 전 간단한 사전 인터뷰 진행하려고 전화드렸습니다. 편하게 답하시면 됩니다.", en: "Hello, I'm calling to do a brief pre-intake interview before your counseling appointment. Feel free to answer at your own pace.", ja: "もしもし、カウンセリング予約前に簡単な事前インタビューを行おうとお電話しました。気楽にお答えいただければ結構です。", zh: "喂，我是想在咨询预约前进行一个简短的初步访谈才打电话的，您可以放松回答就好。", vi: "A lô, tôi gọi để thực hiện một cuộc phỏng vấn ngắn trước khi đặt lịch tư vấn. Anh/chị cứ trả lời thoải mái nhé.", es: "Hola, le llamo para hacer una breve entrevista previa antes de su cita de terapia. Puede responder con toda tranquilidad." },
      { speaker: "내담자", kr: "네, 사실 요즘 잠도 잘 못 자고 일에 집중이 안 돼서 상담을 신청하게 됐어요.", en: "Sure, honestly I've been sleeping poorly and can't focus at work lately, which is why I signed up for counseling.", ja: "はい、実は最近よく眠れなくて仕事にも集中できず、それでカウンセリングを申し込みました。", zh: "好的，其实最近我睡不好，工作也没法集中精神，所以才申请了咨询。", vi: "Vâng, thật ra gần đây tôi ngủ không ngon và không thể tập trung vào công việc nên đã đăng ký tư vấn.", es: "Sí, la verdad es que últimamente duermo mal y no puedo concentrarme en el trabajo, por eso pedí la consulta." },
      { speaker: "상담사", kr: "그런 상태가 지속된 지는 얼마나 되셨나요? 특정 계기가 있었는지도 궁금합니다.", en: "How long has this state persisted? I'm also curious if there was a specific trigger.", ja: "そういう状態が続いてどれくらいになりますか? 特定のきっかけがあったのかも気になります。", zh: "这种状态持续多久了呢？我也很好奇是不是有什么具体的诱因。", vi: "Tình trạng đó kéo dài bao lâu rồi ạ? Tôi cũng tò mò có nguyên nhân cụ thể nào không.", es: "¿Desde hace cuánto tiempo dura ese estado? También me gustaría saber si hubo algún desencadenante en particular." },
      { speaker: "내담자", kr: "한 두 달 정도 됐는데, 직장에서 큰 프로젝트가 실패한 이후로 계속 자책하게 되더라고요.", en: "It's been about two months, and ever since a big project at work failed, I keep blaming myself over and over.", ja: "一、二か月くらいなんですが、職場で大きなプロジェクトが失敗してから、ずっと自分を責めてしまうんです。", zh: "大概一两个月了，自从公司一个大项目失败之后，我就一直在自责。", vi: "Khoảng một hai tháng rồi, kể từ khi dự án lớn ở công ty thất bại, tôi cứ liên tục tự trách bản thân.", es: "Hace uno o dos meses, y desde que fracasó un proyecto grande en el trabajo, no dejo de culparme a mí mismo." },
      { speaker: "상담사", kr: "그 일로 인해 스스로를 어떻게 평가하게 되셨는지, 조금 더 구체적으로 말씀해 주실 수 있을까요?", en: "Could you tell me a bit more specifically how that experience has shaped how you evaluate yourself?", ja: "そのことでご自分をどう評価するようになったか、もう少し具体的にお話しいただけますか?", zh: "能不能再具体说说，那件事让您如何评价自己？", vi: "Anh/chị có thể nói cụ thể hơn một chút, việc đó khiến anh/chị tự đánh giá bản thân mình như thế nào không ạ?", es: "¿Podría contarme con un poco más de detalle cómo esa experiencia ha influido en cómo se evalúa a sí mismo?" },
      { speaker: "내담자", kr: "무능하다는 생각이 계속 들고, 동료들 보기도 부끄러워서 요즘은 사람 만나는 것도 피하게 됐어요.", en: "I keep feeling incompetent, and I'm embarrassed to face my colleagues, so lately I've been avoiding people altogether.", ja: "無能だという思いがずっと続いて、同僚に会うのも恥ずかしくて、最近は人に会うこと自体を避けています。", zh: "一直觉得自己很无能，见到同事都觉得羞愧，最近连见人都开始回避了。", vi: "Tôi cứ nghĩ mình bất tài, ngại nhìn mặt đồng nghiệp nên gần đây cũng tránh gặp gỡ mọi người.", es: "No dejo de pensar que soy incompetente, y me da vergüenza ver a mis compañeros, así que últimamente he estado evitando a la gente por completo." },
      { speaker: "상담사", kr: "많이 힘드셨겠네요. 우선 첫 회기에서는 이런 감정들이 어디서 비롯됐는지 함께 살펴보는 시간을 가지려고 합니다.", en: "That must have been really hard. In the first session, we'll take time together to explore where these feelings are coming from.", ja: "それはとても辛かったでしょうね。まず初回セッションでは、こういった感情がどこから来ているのかを一緒に見ていく時間を持とうと思います。", zh: "那一定很辛苦吧。首次咨询中，我们会先花时间一起探讨一下这些情绪的来源。", vi: "Chắc hẳn anh/chị đã rất vất vả. Trước tiên trong buổi đầu tiên, chúng ta sẽ dành thời gian cùng tìm hiểu xem những cảm xúc này bắt nguồn từ đâu.", es: "Debe de haber sido muy difícil. En la primera sesión dedicaremos tiempo a explorar juntos de dónde vienen estos sentimientos." },
      { speaker: "내담자", kr: "네, 감사합니다. 근데 상담 내용은 철저히 비밀이 보장되는 거 맞죠?", en: "Okay, thank you. But the content of our sessions is strictly confidential, right?", ja: "はい、ありがとうございます。ところでカウンセリングの内容は完全に秘密が守られるんですよね?", zh: "好的，谢谢您。不过咨询的内容是绝对保密的，对吧？", vi: "Vâng, cảm ơn chị. Nhưng nội dung tư vấn được giữ bí mật tuyệt đối đúng không ạ?", es: "Sí, gracias. Por cierto, el contenido de la sesión se mantiene estrictamente confidencial, ¿verdad?" },
      { speaker: "상담사", kr: "네, 법적으로 예외가 되는 극히 일부 상황을 제외하고는 절대 외부에 공개되지 않으니 안심하셔도 됩니다.", en: "Yes, except for a very few legally mandated exceptions, it's never disclosed externally, so you can rest assured.", ja: "はい、法的に例外となるごく一部の状況を除いては絶対に外部に公開されませんので、ご安心ください。", zh: "是的，除了极少数法律规定的例外情况，绝对不会对外公开，请您放心。", vi: "Vâng, ngoại trừ một số ít trường hợp bắt buộc theo pháp luật, tuyệt đối không được tiết lộ ra ngoài, anh/chị có thể yên tâm.", es: "Sí, salvo unas pocas excepciones exigidas por la ley, nunca se divulga fuera de aquí, así que puede quedarse tranquilo." },
    ],
  },
  {
    id: "phone-c2y-pollster-election",
    situationKey: "phone",
    level: "C2",
    title: { en: "A radio call-in discusses a controversial local election result", ja: "ラジオが物議を醸した地方選挙結果を議論する", zh: "电台节目讨论备受争议的地方选举结果", vi: "Chương trình radio bàn về kết quả bầu cử địa phương gây tranh cãi", es: "Un programa de radio abierto al público debate un resultado electoral local polémico" },
    lines: [
      { speaker: "진행자", kr: "오늘은 지난 지방선거 결과를 두고 여론조사 전문가 한 분을 전화로 모셔서 이야기 나눠보겠습니다. 안녕하세요.", en: "Today we're joined by phone with a polling expert to discuss the results of the recent local election. Hello.", ja: "今日は先日の地方選挙の結果について、世論調査専門家をお電話でお迎えしてお話を伺います。こんにちは。", zh: "今天我们通过电话请到一位民调专家，就上次地方选举的结果进行探讨。您好。", vi: "Hôm nay chúng tôi mời một chuyên gia khảo sát dư luận qua điện thoại để bàn về kết quả cuộc bầu cử địa phương vừa qua. Xin chào ông.", es: "Hoy nos acompaña por teléfono un experto en encuestas para hablar de los resultados de las últimas elecciones locales. Buenos días." },
      { speaker: "전문가", kr: "안녕하세요, 반갑습니다. 이번 선거는 사전 여론조사와 실제 결과의 괴리가 유독 컸던 사례로 꼽히고 있죠.", en: "Hello, glad to be here. This election stands out as a case where the gap between pre-election polls and actual results was unusually large.", ja: "こんにちは、お招きありがとうございます。今回の選挙は事前世論調査と実際の結果の乖離が特に大きかった事例として挙げられていますね。", zh: "您好，很高兴受邀。这次选举被认为是选前民调与实际结果差距特别大的一个案例。", vi: "Xin chào, rất vui được tham gia. Cuộc bầu cử lần này được xem là trường hợp có độ lệch đặc biệt lớn giữa khảo sát trước bầu cử và kết quả thực tế.", es: "Buenos días, encantado de estar aquí. Estas elecciones se destacan como un caso donde la brecha entre las encuestas previas y el resultado real fue particularmente grande." },
      { speaker: "진행자", kr: "그 괴리의 원인을 어떻게 분석하고 계신가요? 표본 설계 문제라는 지적도 있던데요.", en: "How do you analyze the cause of that gap? Some have pointed to sample design issues.", ja: "その乖離の原因をどう分析されていますか? 標本設計の問題だという指摘もありますが。", zh: "您怎么分析那种差距的原因？也有人指出是样本设计的问题。", vi: "Ông phân tích nguyên nhân của độ lệch đó thế nào ạ? Cũng có ý kiến cho rằng đó là vấn đề thiết kế mẫu khảo sát.", es: "¿Cómo analiza usted el origen de esa brecha? Hay quienes señalan un problema en el diseño de la muestra." },
      { speaker: "전문가", kr: "표본 문제도 있지만, 저는 이번엔 이른바 샤이 보수 현상보다는 투표율 예측 실패가 더 결정적이었다고 봅니다.", en: "Sample issues played a role, but this time I think a failure to predict turnout was more decisive than the so-called shy conservative effect.", ja: "標本の問題もありますが、私は今回はいわゆるシャイ保守現象よりも投票率予測の失敗の方がより決定的だったと見ています。", zh: "样本问题确实存在，但我认为这次比起所谓的沉默保守派现象，投票率预测失败更具决定性。", vi: "Vấn đề mẫu cũng có, nhưng tôi cho rằng lần này việc dự đoán sai tỷ lệ đi bầu mới là yếu tố quyết định hơn hiện tượng gọi là 'phe bảo thủ thầm lặng'.", es: "El problema de la muestra existe, pero en esta ocasión creo que un fallo en la predicción de la participación fue más determinante que el llamado efecto del votante conservador silencioso." },
      { speaker: "청취자", kr: "여보세요, 청취자인데요. 그런데 젊은 층 투표율이 예상보다 높았다는 게 결과에 어떤 영향을 미친 건가요?", en: "Hello, this is a listener. But how did the higher-than-expected turnout among younger voters affect the outcome?", ja: "もしもし、リスナーです。ところで若年層の投票率が予想より高かったことが結果にどんな影響を与えたんですか?", zh: "喂，我是听众。不过年轻群体的投票率高于预期，这对结果产生了怎样的影响呢？", vi: "A lô, tôi là thính giả đây ạ. Nhưng việc tỷ lệ đi bầu của tầng lớp trẻ cao hơn dự kiến đã ảnh hưởng thế nào đến kết quả vậy ạ?", es: "Hola, soy oyente. Pero, ¿cómo influyó en el resultado que la participación entre los jóvenes fuera más alta de lo esperado?" },
      { speaker: "전문가", kr: "좋은 질문입니다. 젊은 유권자들이 SNS를 통해 결집하면서 기존 여론조사 표본에 충분히 반영되지 못했던 겁니다.", en: "Good question. Younger voters mobilized through social media, and that wasn't sufficiently captured in the existing polling samples.", ja: "いい質問です。若い有権者たちがSNSを通じて結集したことが、既存の世論調査の標本に十分反映されていなかったんです。", zh: "这是个好问题。年轻选民通过社交媒体聚集起来，这一点没有被充分反映在原有的民调样本中。", vi: "Câu hỏi hay đấy. Cử tri trẻ tập hợp qua mạng xã hội, điều này chưa được phản ánh đầy đủ trong mẫu khảo sát dư luận hiện có.", es: "Buena pregunta. Los votantes jóvenes se movilizaron a través de las redes sociales, y eso no quedó suficientemente reflejado en las muestras de las encuestas existentes." },
      { speaker: "진행자", kr: "그렇다면 앞으로 여론조사 방식에도 근본적인 변화가 필요하다는 뜻인가요?", en: "Does that mean fundamental changes are needed in polling methodology going forward?", ja: "それなら今後、世論調査の方式にも根本的な変化が必要だということですか?", zh: "那么今后民调方式也需要根本性的变化吗？", vi: "Vậy nghĩa là tới đây phương thức khảo sát dư luận cũng cần thay đổi mang tính căn bản sao ạ?", es: "Entonces, ¿eso significa que a partir de ahora hace falta un cambio de fondo en la metodología de las encuestas?" },
      { speaker: "전문가", kr: "네, 전화 조사 위주의 방식만으로는 한계가 뚜렷합니다. 온라인 패널과 결합한 혼합 방식이 대안으로 논의되고 있습니다.", en: "Yes, relying mainly on phone surveys clearly has limits. A mixed method combined with online panels is being discussed as an alternative.", ja: "はい、電話調査中心のやり方だけでは限界が明らかです。オンラインパネルと組み合わせた混合方式が代案として議論されています。", zh: "是的，仅靠以电话调查为主的方式局限性很明显，将其与在线样本小组结合的混合方式正被作为替代方案讨论。", vi: "Vâng, chỉ dựa vào phương thức khảo sát qua điện thoại đã bộc lộ giới hạn rõ ràng. Phương thức kết hợp với nhóm khảo sát trực tuyến đang được bàn đến như một giải pháp thay thế.", es: "Sí, depender principalmente de encuestas telefónicas tiene límites claros. Se está debatiendo como alternativa un método mixto combinado con paneles en línea." },
      { speaker: "청취자", kr: "그럼 이번 결과를 두고 여론조사 자체의 신뢰도가 무너졌다고 봐야 하는 건가요?", en: "So should we conclude that the credibility of polling itself has collapsed because of this result?", ja: "それでは今回の結果を受けて、世論調査そのものの信頼度が崩れたと見るべきなんでしょうか?", zh: "那这次的结果，是不是应该看作民调本身的可信度崩塌了呢？", vi: "Vậy nhìn vào kết quả lần này, có nên xem là độ tin cậy của bản thân khảo sát dư luận đã sụp đổ không ạ?", es: "Entonces, ¿deberíamos concluir que con este resultado se ha derrumbado la credibilidad de las encuestas en sí?" },
      { speaker: "전문가", kr: "신뢰도가 무너졌다기보다는, 방법론을 시급히 재정비해야 한다는 경고 신호로 받아들이는 게 맞다고 봅니다.", en: "I wouldn't say credibility has collapsed—rather, I think it should be taken as an urgent warning sign to overhaul the methodology.", ja: "信頼度が崩れたというより、方法論を早急に立て直すべきだという警告のサインとして受け止めるのが正しいと思います。", zh: "与其说信任度崩塌了，不如说这应看作是必须尽快重整方法论的一个警示信号。", vi: "Tôi cho rằng thay vì nói độ tin cậy đã sụp đổ, nên xem đây là tín hiệu cảnh báo cần chỉnh đốn phương pháp luận gấp rút.", es: "Más que decir que la credibilidad se ha derrumbado, creo que debe tomarse como una señal de alarma urgente para reformar la metodología." },
    ],
  },
  {
    id: "phone-c2y-labor-automation",
    situationKey: "phone",
    level: "C2",
    title: { en: "A podcast call-in debates automation and job loss", ja: "ポッドキャストで自動化と失業を議論する", zh: "播客节目辩论自动化与失业问题", vi: "Cuộc gọi vào podcast tranh luận về tự động hóa và mất việc làm", es: "Una llamada a un pódcast debate la automatización y la pérdida de empleo" },
    lines: [
      { speaker: "진행자", kr: "오늘 주제는 자동화가 일자리에 미치는 영향인데요, 노동경제학자 한 분을 전화로 모셨습니다.", en: "Today's topic is automation's impact on jobs, and we have a labor economist joining us by phone.", ja: "今日のテーマは自動化が雇用に与える影響ですが、労働経済学者の方を電話でお迎えしています。", zh: "今天的主题是自动化对就业的影响，我们通过电话请到一位劳动经济学家。", vi: "Chủ đề hôm nay là ảnh hưởng của tự động hóa đến việc làm, chúng tôi mời một nhà kinh tế học lao động qua điện thoại.", es: "El tema de hoy es el impacto de la automatización en el empleo, y nos acompaña por teléfono un economista laboral." },
      { speaker: "경제학자", kr: "안녕하세요. 결론부터 말씀드리면 자동화가 일자리를 없앤다는 담론은 지나치게 단순화된 측면이 있습니다.", en: "Hello. To cut to the chase, the narrative that automation destroys jobs is, in a way, an overly simplified one.", ja: "こんにちは。結論から申し上げると、自動化が雇用を奪うという言説はある意味過度に単純化された面があります。", zh: "您好。先说结论，自动化会消灭工作岗位这种说法，某种程度上是过度简化了。", vi: "Xin chào. Nói trước kết luận, luận điểm cho rằng tự động hóa làm mất việc làm có phần bị đơn giản hóa quá mức.", es: "Buenos días. Yendo directo al grano, el discurso de que la automatización destruye empleos es, en cierto sentido, una simplificación excesiva." },
      { speaker: "진행자", kr: "그렇게 보시는 근거가 궁금한데요. 실제로 제조업 현장에서는 인력 감축이 계속되고 있지 않습니까?", en: "I'm curious what grounds you for that view. Hasn't workforce reduction been ongoing in manufacturing settings?", ja: "そう見られる根拠が気になりますね。実際に製造業の現場では人員削減が続いているじゃないですか。", zh: "我很好奇您这么看的依据。实际上制造业现场不是一直在裁员吗？", vi: "Tôi tò mò căn cứ nào để ông nhìn nhận như vậy. Thực tế trong lĩnh vực sản xuất, việc cắt giảm nhân sự vẫn đang tiếp diễn đấy chứ ạ?", es: "Tengo curiosidad por saber en qué se basa esa opinión. ¿No es cierto que en las plantas de fabricación se sigue reduciendo personal?" },
      { speaker: "경제학자", kr: "감축이 있는 건 사실이지만, 동시에 새로운 직군이 생겨나는 창출 효과도 무시할 수 없습니다. 다만 그 이행 과정에서 마찰이 발생하는 거죠.", en: "Reductions are real, but the job-creation effect from new occupations emerging simultaneously can't be ignored either. The friction occurs during the transition process, though.", ja: "削減があるのは事実ですが、同時に新しい職種が生まれる創出効果も無視できません。ただ、その移行過程で摩擦が発生するんです。", zh: "裁员确实存在，但同时新职业种类不断出现的创造效应也不能忽视，只是在过渡过程中会产生摩擦。", vi: "Việc cắt giảm là có thật, nhưng đồng thời hiệu ứng tạo ra ngành nghề mới cũng không thể xem nhẹ. Chỉ là ma sát sẽ xảy ra trong quá trình chuyển đổi đó thôi.", es: "Es cierto que hay reducciones, pero tampoco se puede ignorar el efecto de creación de nuevos puestos que surgen al mismo tiempo. Aun así, el proceso de transición genera fricción." },
      { speaker: "청취자", kr: "여보세요, 저는 제조업 종사자인데요. 창출된 일자리라는 게 결국 고학력자 중심 아닌가요? 저희 같은 사람들한테는 그림의 떡이에요.", en: "Hello, I work in manufacturing. Aren't those newly created jobs ultimately centered on highly educated workers? For people like us, it's a pie in the sky.", ja: "もしもし、私は製造業の従事者ですが。創出される仕事というのは結局高学歴者中心じゃないですか? 私たちみたいな人間には絵に描いた餅ですよ。", zh: "喂，我是制造业从业者。创造出来的工作岗位说到底不还是以高学历人群为中心吗？对我们这样的人来说就是画饼。", vi: "A lô, tôi là người làm trong ngành sản xuất. Những việc làm được tạo ra đó chẳng phải chủ yếu dành cho người có học vấn cao sao? Với người như chúng tôi thì đó chỉ là bánh vẽ thôi.", es: "Hola, trabajo en el sector manufacturero. ¿Esos empleos creados no terminan siendo sobre todo para personas con estudios superiores? Para gente como nosotros es como un espejismo." },
      { speaker: "경제학자", kr: "뼈아픈 지적입니다. 재교육 체계가 뒷받침되지 않으면 그 격차는 오히려 심화될 수밖에 없습니다. 정책적 개입이 필수적인 이유입니다.", en: "That's a painful but valid point. Without a supporting retraining system, that gap could only widen further. This is exactly why policy intervention is essential.", ja: "痛い指摘ですね。再教育体系が支えとして機能しなければ、その格差はむしろ深刻化する一方です。政策的介入が必須である理由がそこにあります。", zh: "这是个痛点。如果再教育体系不能起到支撑作用，那种差距只会进一步恶化，这正是政策介入必不可少的原因。", vi: "Đây là điểm chỉ trích rất đau. Nếu không có hệ thống đào tạo lại hỗ trợ, khoảng cách đó chỉ càng thêm sâu sắc. Đây chính là lý do việc can thiệp chính sách là cần thiết.", es: "Es una observación dolorosa pero certera. Sin un sistema de reciclaje profesional que lo respalde, esa brecha solo puede profundizarse. Por eso la intervención de política pública es imprescindible." },
      { speaker: "진행자", kr: "그럼 어떤 정책이 실효성이 있다고 보십니까? 기본소득 같은 극단적인 대안도 거론되고 있잖아요.", en: "So what policies do you think would be effective? Radical alternatives like universal basic income are being floated too.", ja: "それではどんな政策が実効性があるとお考えですか? ベーシックインカムのような極端な代案も取り沙汰されていますが。", zh: "那您认为什么样的政策才具有实效？基本收入之类的极端方案也在被讨论。", vi: "Vậy ông thấy chính sách nào thực sự hiệu quả? Cũng có ý kiến đề cập đến phương án cực đoan như thu nhập cơ bản.", es: "Entonces, ¿qué políticas cree que serían realmente eficaces? También se habla de alternativas radicales como la renta básica." },
      { speaker: "경제학자", kr: "기본소득은 논쟁적인 카드입니다. 저는 그보다 산업 전환기의 맞춤형 직업훈련과 전환 수당이 우선돼야 한다고 봅니다.", en: "Basic income is a contentious card to play. I think tailored vocational retraining and transition allowances during the industrial shift should come first instead.", ja: "ベーシックインカムは議論の的です。私はそれより産業転換期の職業訓練プログラムと転換手当の方を優先すべきだと考えます。", zh: "基本收入是个有争议的方案，我认为比起那个，产业转型期的定制职业培训和转型补贴更应该优先考虑。", vi: "Thu nhập cơ bản là một lá bài gây tranh cãi. Tôi cho rằng nên ưu tiên đào tạo nghề phù hợp và trợ cấp chuyển đổi trong giai đoạn chuyển đổi ngành hơn.", es: "La renta básica es una carta polémica. Creo que antes deberían priorizarse la capacitación laboral adaptada y las ayudas de transición durante el cambio industrial." },
      { speaker: "청취자", kr: "말씀은 좋은데, 그런 훈련 프로그램이 실제로 효과가 있었던 사례가 있나요? 다들 이론만 얘기하는 것 같아서요.", en: "That sounds good in theory, but are there actual cases where such training programs worked? It feels like everyone just talks theory.", ja: "お話は良さそうですが、そういう訓練プログラムが実際に効果があった事例はあるんですか? みんな理論ばかり話しているように思えて。", zh: "听起来不错，但那种培训项目实际上有真正见效的案例吗？感觉大家都只是在讲理论。", vi: "Nghe hay đấy, nhưng có trường hợp nào chương trình đào tạo đó thực sự hiệu quả không ạ? Cảm giác mọi người chỉ toàn nói lý thuyết thôi.", es: "Suena bien en teoría, pero ¿hay casos donde esos programas de capacitación hayan funcionado realmente? Parece que todos hablan solo de teoría." },
      { speaker: "경제학자", kr: "북유럽 일부 국가의 사례가 참고할 만합니다. 물론 우리 실정에 그대로 이식하긴 어렵지만, 방향성만큼은 배울 점이 많습니다.", en: "Some Nordic countries offer useful reference cases. Of course, it's hard to transplant them directly into our context, but there's a lot to learn in terms of direction.", ja: "北欧の一部の国の事例が参考になります。もちろん私たちの実情にそのまま移植するのは難しいですが、方向性については学ぶ点が多いです。", zh: "北欧一些国家的案例值得参考。当然，直接照搬到我们的实际情况有难度，但在方向上有很多值得学习的地方。", vi: "Trường hợp một số nước Bắc Âu đáng để tham khảo. Tất nhiên khó áp dụng nguyên xi vào hoàn cảnh nước ta, nhưng về mặt định hướng thì có nhiều điều đáng học hỏi.", es: "Los casos de algunos países nórdicos son un buen referente. Por supuesto, es difícil trasladarlos tal cual a nuestra realidad, pero hay mucho que aprender en cuanto a la orientación." },
    ],
  },
  {
    id: "phone-c2y-plagiarism-scandal",
    situationKey: "phone",
    level: "C2",
    title: { en: "A journalist phone-interviews an academic about a plagiarism scandal", ja: "記者が電話で盗用疑惑について学者にインタビューする", zh: "记者电话采访学者了解论文抄袭疑云", vi: "Nhà báo phỏng vấn học giả qua điện thoại về nghi án đạo văn", es: "Un periodista entrevista por teléfono a un académico sobre un escándalo de plagio" },
    lines: [
      { speaker: "기자", kr: "여보세요, 최근 불거진 논문 표절 의혹 관련해서 학회 입장을 여쭤보고 싶어 연락드렸습니다.", en: "Hello, I'm calling to ask about the academic society's position on the recent plagiarism allegations that have surfaced.", ja: "もしもし、最近浮上した論文盗用疑惑に関して学会の立場をお伺いしたくてお電話しました。", zh: "喂，是想问一下学会对最近浮出的论文抄袭嫌疑的立场，所以打电话给您。", vi: "A lô, tôi muốn hỏi lập trường của hội đồng học thuật về nghi án đạo văn vừa nổi lên gần đây.", es: "Hola, le llamo porque quería preguntarle la postura de la sociedad académica sobre las recientes acusaciones de plagio que han salido a la luz." },
      { speaker: "교수", kr: "네, 저희도 상황을 예의주시하고 있습니다. 다만 아직 검증위원회의 최종 결론이 나오지 않아서 신중하게 말씀드려야 할 것 같습니다.", en: "Yes, we're closely monitoring the situation as well. But since the verification committee hasn't reached a final conclusion, I need to be cautious about what I say.", ja: "はい、私たちも状況を注視しています。ただ、まだ検証委員会の最終結論が出ていないので、慎重にお答えしなければなりません。", zh: "是的，我们也在密切关注这个情况。不过检证委员会还没有得出最终结论，我需要谨慎回答。", vi: "Vâng, chúng tôi cũng đang theo dõi sát tình hình. Chỉ là ủy ban kiểm chứng chưa có kết luận cuối cùng nên tôi phải trả lời một cách thận trọng.", es: "Sí, nosotros también estamos siguiendo la situación de cerca. Pero como el comité de verificación aún no ha llegado a una conclusión final, debo ser cauteloso al hablar." },
      { speaker: "기자", kr: "일부 언론에서는 이미 표절이 명백하다는 식으로 보도가 나가고 있는데, 이에 대해서는 어떻게 보십니까?", en: "Some media outlets are already reporting it as if the plagiarism were clear-cut. What's your view on that?", ja: "一部のメディアではすでに盗用が明白だという式で報道が出ていますが、これについてはどうお考えですか?", zh: "有些媒体已经用「抄袭已经很明显」的方式在报道了，您对此怎么看？", vi: "Một số cơ quan truyền thông đã đưa tin theo hướng khẳng định đạo văn là rõ ràng, ông nghĩ sao về điều này?", es: "Algunos medios ya lo están reportando como si el plagio fuera evidente. ¿Qué opina de eso?" },
      { speaker: "교수", kr: "성급한 판단이라고 생각합니다. 유사도 검사 결과만으로 표절 여부를 단정하는 건 학문적 절차를 무시하는 처사입니다.", en: "I think that's a hasty judgment. Determining plagiarism based solely on a similarity check result disregards proper academic procedure.", ja: "性急な判断だと思います。類似度検査の結果だけで盗用の有無を断定するのは学問的手続きを無視することになります。", zh: "我认为那是过于草率的判断。仅凭相似度检测结果就断定是否抄袭，是无视了学术程序。", vi: "Tôi nghĩ đó là phán đoán hấp tấp. Chỉ dựa vào kết quả kiểm tra độ tương đồng để kết luận có đạo văn hay không là phớt lờ quy trình học thuật.", es: "Me parece un juicio precipitado. Determinar si hubo plagio basándose únicamente en un resultado de detección de similitud ignora el procedimiento académico adecuado." },
      { speaker: "기자", kr: "그렇다면 검증위원회의 판단 기준은 구체적으로 어떻게 되나요? 유사도 외에 어떤 요소를 보시는 건가요?", en: "Then what exactly are the committee's evaluation criteria? What factors besides similarity are being considered?", ja: "それでは検証委員会の判断基準は具体的にどうなっているんですか? 類似度以外にどんな要素を見るんですか?", zh: "那检证委员会的判断标准具体是怎样的呢？除了相似度之外还会看哪些要素？", vi: "Vậy tiêu chuẩn đánh giá cụ thể của ủy ban kiểm chứng là gì ạ? Ngoài độ tương đồng, còn xem xét yếu tố nào nữa ạ?", es: "Entonces, ¿cuáles son exactamente los criterios de evaluación del comité de verificación? Además de la similitud, ¿qué otros factores tienen en cuenta?" },
      { speaker: "교수", kr: "인용 관행, 저자 간 기여도, 선행 연구와의 시기적 선후 관계 등을 종합적으로 검토합니다. 단순 비교로 결론 내릴 사안이 아닙니다.", en: "We comprehensively review citation practices, contribution levels among authors, and the chronological relationship with prior research. It's not a matter to be concluded through simple comparison.", ja: "引用慣行、著者間の貢献度、先行研究との時期的な前後関係などを総合的に検討します。単純比較で結論を出す事案ではありません。", zh: "会综合审查引用惯例、作者之间的贡献度、与先行研究的时间先后关系等，这不是靠简单比较就能得出结论的事。", vi: "Chúng tôi xem xét tổng hợp thông lệ trích dẫn, mức đóng góp giữa các tác giả, mối quan hệ trước sau về thời điểm với các nghiên cứu trước đó. Đây không phải vấn đề có thể kết luận bằng so sánh đơn giản.", es: "Se revisan de forma integral las prácticas de citación, el grado de contribución entre los autores y la relación cronológica con investigaciones previas. No es un asunto que se pueda concluir con una simple comparación." },
      { speaker: "기자", kr: "만약 표절로 판명될 경우, 학회 차원의 후속 조치는 어떻게 진행되나요?", en: "If it's ultimately determined to be plagiarism, how will the society proceed with follow-up measures?", ja: "もし盗用と判明した場合、学会レベルの後続措置はどう進められますか?", zh: "如果最终被认定为抄袭，学会层面的后续措施将如何进行？", vi: "Nếu bị xác định là đạo văn, biện pháp tiếp theo ở cấp hội đồng học thuật sẽ ra sao ạ?", es: "Si finalmente se determina que hubo plagio, ¿cómo procederá la sociedad académica con las medidas posteriores?" },
      { speaker: "교수", kr: "논문 게재 취소는 물론이고, 해당 연구자의 향후 투고 제한까지 검토될 수 있습니다. 다만 그 전에 소명 기회는 반드시 보장됩니다.", en: "Retraction of the paper, of course, and even restrictions on the researcher's future submissions could be considered. That said, an opportunity to respond will absolutely be guaranteed beforehand.", ja: "論文掲載取り消しはもちろん、当該研究者の今後の投稿制限まで検討され得ます。ただ、その前に釈明の機会は必ず保障されます。", zh: "论文撤稿是必然的，甚至可能考虑限制该研究者今后的投稿资格。不过在那之前，一定会保障其陈述辩解的机会。", vi: "Đương nhiên là rút bài, thậm chí có thể xem xét hạn chế đăng bài tương lai của nhà nghiên cứu đó. Chỉ là trước đó nhất định phải đảm bảo cơ hội trình bày biện minh.", es: "Por supuesto, la retractación del artículo, e incluso podría considerarse restringir futuras publicaciones del investigador. Aun así, antes de eso se garantizará sin falta la oportunidad de dar explicaciones." },
      { speaker: "기자", kr: "알겠습니다. 최종 결론이 나오면 다시 인터뷰 요청드려도 될까요?", en: "Understood. May I request another interview once the final conclusion is out?", ja: "分かりました。最終結論が出たらまたインタビューをお願いしてもよろしいですか?", zh: "明白了。等最终结论出来后，我可以再次请求采访吗？", vi: "Tôi hiểu rồi. Khi có kết luận cuối cùng, tôi có thể xin phỏng vấn lại được không ạ?", es: "Entendido. ¿Podría solicitarle otra entrevista cuando se conozca la conclusión final?" },
      { speaker: "교수", kr: "네, 결과가 확정되는 대로 성실히 답변드리겠습니다.", en: "Yes, I'll respond in good faith as soon as the outcome is finalized.", ja: "はい、結果が確定次第、誠実にお答えします。", zh: "可以，结果一确定我会认真配合回答的。", vi: "Vâng, khi kết quả được xác định, tôi sẽ trả lời nghiêm túc ngay.", es: "Sí, en cuanto se confirme el resultado responderé con toda honestidad." },
    ],
  },
  {
    id: "phone-c2y-gentrification",
    situationKey: "phone",
    level: "C2",
    title: { en: "A call-in show debates gentrification in an old neighborhood", ja: "ラジオが旧市街のジェントリフィケーションを議論する", zh: "电台辩论老街区的士绅化问题", vi: "Chương trình gọi vào bàn về hiện tượng chỉnh trang đô thị ở khu phố cổ", es: "Un programa de llamadas debate la gentrificación de un barrio antiguo" },
    lines: [
      { speaker: "진행자", kr: "오늘은 원도심 재개발을 둘러싼 젠트리피케이션 문제로 도시사회학자 한 분과 통화 연결돼 있습니다.", en: "Today we're on the phone with an urban sociologist to discuss gentrification surrounding the redevelopment of the old downtown.", ja: "今日は原都心の再開発をめぐるジェントリフィケーション問題について、都市社会学者の方と電話がつながっています。", zh: "今天关于原市中心再开发引发的士绅化问题，我们连线了一位城市社会学家。", vi: "Hôm nay chúng tôi kết nối điện thoại với một nhà xã hội học đô thị để bàn về vấn đề chỉnh trang đô thị xoay quanh việc tái phát triển khu trung tâm cũ.", es: "Hoy estamos conectados por teléfono con una socióloga urbana para hablar de la gentrificación en torno a la reurbanización del centro histórico." },
      { speaker: "학자", kr: "안녕하세요. 이 지역은 최근 몇 년 새 임대료가 급등하면서 기존 상인들이 밀려나는 전형적인 양상을 보이고 있습니다.", en: "Hello. This area has shown a textbook pattern over the past few years, with soaring rents pushing out longtime merchants.", ja: "こんにちは。この地域はここ数年で賃料が急騰して、既存の商人たちが押し出される典型的な様相を見せています。", zh: "您好。这个地区近几年租金暴涨，出现了典型的把原有商户挤出去的现象。", vi: "Xin chào. Khu vực này trong vài năm gần đây giá thuê tăng vọt, cho thấy dạng thức điển hình khi các tiểu thương cũ bị đẩy ra ngoài.", es: "Buenos días. Esta zona ha mostrado en los últimos años un patrón muy típico, con el aumento vertiginoso de los alquileres que ha ido desplazando a los comerciantes de siempre." },
      { speaker: "청취자", kr: "여보세요, 저는 그 동네에서 15년째 가게 하고 있는 사람인데요. 재개발이 다 나쁘다는 식으로 말씀하시는 건 좀 편향된 것 같아요.", en: "Hello, I've run a shop in that neighborhood for 15 years. Framing redevelopment as entirely bad seems a bit one-sided to me.", ja: "もしもし、私はその街で15年間店をやっている者ですが。再開発が全部悪いという言い方は少し偏っているように思います。", zh: "喂，我是在那条街上开了十五年店的人。把再开发说得全是坏事，这种说法感觉有点片面。", vi: "A lô, tôi là người kinh doanh cửa hàng ở khu đó mười lăm năm rồi. Việc nói tái phát triển là xấu hoàn toàn nghe có vẻ hơi thiên vị đấy.", es: "Hola, llevo 15 años con un negocio en ese barrio. Me parece un poco sesgado decir que la reurbanización es totalmente negativa." },
      { speaker: "학자", kr: "재개발 자체를 부정하는 건 아닙니다. 다만 개발 이익이 기존 주민이 아니라 외부 자본에 집중되는 구조가 문제라는 겁니다.", en: "I'm not denying redevelopment itself. The problem is that the structure concentrates development gains in outside capital rather than existing residents.", ja: "再開発そのものを否定しているわけではありません。ただ、開発利益が既存住民ではなく外部資本に集中する構造が問題だということです。", zh: "我不是在否定再开发本身，问题是开发收益集中流向外部资本而不是原有居民的这种结构。", vi: "Tôi không phủ nhận bản thân việc tái phát triển. Chỉ là vấn đề ở cấu trúc khiến lợi ích phát triển tập trung vào vốn bên ngoài chứ không phải cư dân hiện có.", es: "No estoy negando la reurbanización en sí misma. El problema es que la estructura concentra los beneficios del desarrollo en capital externo en lugar de en los residentes de siempre." },
      { speaker: "청취자", kr: "그럼 대안이 뭔가요? 낙후된 상태로 계속 두는 게 주민들한테 더 나은 건 아니잖아요.", en: "Then what's the alternative? Leaving it run-down forever isn't better for residents either, is it?", ja: "それでは代案は何ですか? 老朽化した状態のまま放置するのが住民にとってより良いわけではないですよね。", zh: "那替代方案是什么呢？让它一直破败下去对居民来说也不见得更好吧。", vi: "Vậy phương án thay thế là gì ạ? Cứ để nó xuống cấp mãi cũng đâu tốt hơn cho cư dân.", es: "Entonces, ¿cuál es la alternativa? Dejarlo tal cual, deteriorado, tampoco es mejor para los vecinos, ¿no?" },
      { speaker: "학자", kr: "맞는 말씀입니다. 그래서 저는 상가 임대료 상한제나 원주민 재정착 지원 같은 완충 장치가 병행돼야 한다고 주장하는 겁니다.", en: "That's a fair point. That's why I'm arguing that buffer measures—like commercial rent caps or resettlement support for original residents—need to accompany the process.", ja: "おっしゃる通りです。だから私は商店賃料の上限制や原住民再定着支援のような緩衝装置を並行すべきだと主張しているんです。", zh: "您说得对。所以我主张，商铺租金上限制或原住居民再安置支援这样的缓冲机制应当同步推行。", vi: "Anh nói đúng. Vì vậy tôi chủ trương cần song song có các biện pháp đệm như trần giá thuê mặt bằng hay hỗ trợ tái định cư cho cư dân gốc.", es: "Tiene razón. Por eso sostengo que deben aplicarse medidas amortiguadoras, como topes al alquiler comercial o apoyo al reasentamiento de los residentes originales." },
      { speaker: "진행자", kr: "실제로 그런 제도가 도입된 사례가 있습니까? 이론적으로만 그럴듯한 건 아닌지 궁금하네요.", en: "Are there actual cases where such systems have been introduced? I'm curious whether this is just plausible in theory.", ja: "実際にそういう制度が導入された事例はありますか? 理論的にもっともらしいだけではないか気になりますね。", zh: "实际上有引入过这种制度的案例吗？我很好奇这是不是只在理论上说得通。", vi: "Thực tế có trường hợp nào áp dụng chế độ như vậy chưa ạ? Tôi tò mò không biết có chỉ là nghe hợp lý trên lý thuyết thôi không.", es: "¿Existen casos reales donde se haya implantado ese tipo de sistema? Me pregunto si esto no es solo plausible en la teoría." },
      { speaker: "학자", kr: "일부 지자체에서 상생협약 형태로 시도하고 있지만, 강제성이 없어서 실효성 논란이 끊이지 않는 게 현실입니다.", en: "Some local governments are attempting it through voluntary coexistence agreements, but the reality is that debate over their effectiveness persists because they lack enforceability.", ja: "一部の自治体で相生協約の形で試みていますが、強制力がなくて実効性の論争が絶えないのが現実です。", zh: "一些地方政府正以共生协约的形式尝试，但由于缺乏强制力，关于其实效性的争论一直没有停过。", vi: "Một số địa phương đang thử nghiệm dưới dạng thỏa ước cùng thắng, nhưng vì không có tính bắt buộc nên tranh cãi về hiệu quả thực tế vẫn chưa dứt.", es: "Algunos gobiernos locales lo están intentando en forma de acuerdos de convivencia, pero la realidad es que, al no ser vinculantes, la controversia sobre su eficacia no cesa." },
      { speaker: "청취자", kr: "결국 법적 강제력이 없으면 다 구호에 그친다는 말씀이시네요. 씁쓸하지만 공감이 갑니다.", en: "So in the end, without legal enforcement, it all amounts to empty slogans. It's a bitter point, but I can relate.", ja: "結局、法的な強制力がなければ全部スローガンに終わるということですね。苦いですけど共感します。", zh: "那意思是说，没有法律强制力的话，最终都只会沦为口号。虽然听着苦涩，但我很有共鸣。", vi: "Vậy nói cách khác, nếu không có tính bắt buộc pháp lý thì tất cả chỉ dừng lại ở khẩu hiệu thôi. Nghe hơi chua chát nhưng tôi cũng đồng cảm.", es: "Entonces, al final, sin fuerza legal vinculante, todo se queda en meras consignas. Es amargo, pero lo entiendo perfectamente." },
      { speaker: "학자", kr: "네, 그래서 조례 차원에서라도 강제력 있는 장치를 마련하자는 논의가 최근 다시 불붙고 있는 상황입니다.", en: "Right, which is why discussions have recently reignited on establishing enforceable measures at least at the municipal ordinance level.", ja: "はい、だから条例レベルでも強制力のある装置を用意しようという議論が最近また活発になっている状況です。", zh: "是的，所以最近关于至少在条例层面设立具有强制力的机制的讨论又重新热了起来。", vi: "Vâng, chính vì thế mà gần đây thảo luận về việc thiết lập cơ chế mang tính bắt buộc ở cấp pháp lệnh cũng đang nóng trở lại.", es: "Sí, por eso recientemente se ha reavivado el debate sobre establecer al menos, a nivel de ordenanza municipal, mecanismos con fuerza vinculante." },
    ],
  },
  {
    id: "phone-c2y-ai-copyright",
    situationKey: "phone",
    level: "C2",
    title: { en: "A radio debate on AI-generated art and copyright", ja: "ラジオが生成AIアートと著作権を討論する", zh: "电台辩论AI生成艺术与版权问题", vi: "Cuộc tranh luận trên radio về nghệ thuật do AI tạo ra và bản quyền", es: "Un debate de radio sobre el arte generado por IA y los derechos de autor" },
    lines: [
      { speaker: "진행자", kr: "오늘은 생성형 인공지능이 만든 작품의 저작권 문제를 두고 저작권법 전문 변호사님과 통화로 이야기 나눠보겠습니다.", en: "Today we'll discuss copyright issues surrounding AI-generated works, in a phone conversation with a copyright law attorney.", ja: "今日は生成型人工知能が作った作品の著作権問題について、著作権法専門の弁護士の方と電話でお話しします。", zh: "今天我们通过电话与一位著作权法专业律师，讨论生成式人工智能创作作品的版权问题。", vi: "Hôm nay chúng tôi sẽ trao đổi qua điện thoại với một luật sư chuyên về luật bản quyền về vấn đề bản quyền của các tác phẩm do trí tuệ nhân tạo tạo ra.", es: "Hoy hablaremos por teléfono con un abogado especialista en propiedad intelectual sobre los problemas de derechos de autor en torno a las obras generadas por inteligencia artificial." },
      { speaker: "변호사", kr: "안녕하세요. 현행법상 인공지능이 단독으로 창작한 결과물은 저작물로 인정되지 않는다는 게 원칙입니다.", en: "Hello. Under current law, the principle is that works created solely by AI are not recognized as copyrightable works.", ja: "こんにちは。現行法上、人工知能が単独で創作した結果物は著作物として認められないというのが原則です。", zh: "您好。根据现行法律，原则上人工智能独立创作的成果不被认定为著作物。", vi: "Xin chào. Theo luật hiện hành, nguyên tắc là sản phẩm do trí tuệ nhân tạo sáng tạo đơn thuần không được công nhận là tác phẩm có bản quyền.", es: "Buenos días. Según la ley vigente, el principio es que las obras creadas únicamente por inteligencia artificial no se reconocen como obras protegidas por derechos de autor." },
      { speaker: "청취자", kr: "여보세요, 그런데 사용자가 프롬프트를 정교하게 설계해서 만든 경우는 어떻게 되나요? 그것도 순수 창작물이 아니라고 보시나요?", en: "Hello, but what about cases where a user meticulously designs the prompt to create it? Do you also consider that not a genuine creative work?", ja: "もしもし、それでは利用者がプロンプトを精巧に設計して作った場合はどうなりますか? それも純粋な創作物ではないとお考えですか?", zh: "喂，那如果是用户精心设计提示词创作出来的呢？您也认为那不算是纯粹的创作物吗？", vi: "A lô, vậy trường hợp người dùng thiết kế câu lệnh (prompt) một cách tinh vi để tạo ra thì sao ạ? Ông cũng cho rằng đó không phải là tác phẩm sáng tạo thuần túy sao?", es: "Hola, pero ¿qué pasa cuando el usuario diseña el prompt de forma minuciosa para crearla? ¿También considera que eso no es una obra creativa genuina?" },
      { speaker: "변호사", kr: "그 부분이 최근 쟁점입니다. 프롬프트 설계에 창작적 기여가 인정된다면 부분적으로 보호받을 여지가 있다는 견해도 있습니다.", en: "That's a recent point of contention. There's also a view that if creative contribution through prompt design is recognized, there could be room for partial protection.", ja: "その部分が最近の争点です。プロンプト設計に創作的な寄与が認められれば、部分的に保護される余地があるという見解もあります。", zh: "那部分正是最近的争议点。也有观点认为，如果提示词设计被认定具有创作性贡献，就有可能获得部分保护。", vi: "Đó chính là điểm tranh cãi gần đây. Cũng có quan điểm cho rằng nếu công nhận đóng góp sáng tạo trong việc thiết kế câu lệnh thì có thể được bảo hộ một phần.", es: "Ese es justamente un punto de discusión reciente. También existe la opinión de que, si se reconoce una contribución creativa en el diseño del prompt, podría haber margen para una protección parcial." },
      { speaker: "진행자", kr: "그렇다면 기존 예술가들의 작품을 학습 데이터로 사용한 것에 대해서는 어떤 논란이 있나요?", en: "Then what controversies exist regarding the use of existing artists' works as training data?", ja: "それでは既存のアーティストの作品を学習データとして使用したことについてはどんな論争がありますか?", zh: "那关于把现有艺术家的作品用作训练数据，存在哪些争议呢？", vi: "Vậy về việc sử dụng tác phẩm của các nghệ sĩ hiện có làm dữ liệu huấn luyện thì có tranh cãi gì ạ?", es: "Entonces, ¿qué controversias existen respecto al uso de obras de artistas existentes como datos de entrenamiento?" },
      { speaker: "변호사", kr: "이게 더 뜨거운 쟁점인데요, 동의 없이 저작물을 학습에 활용한 것 자체가 저작권 침해라는 소송이 여러 건 진행 중입니다.", en: "This is an even hotter issue—there are multiple ongoing lawsuits arguing that using copyrighted works for training without consent itself constitutes infringement.", ja: "これがもっと熱い争点ですが、同意なしに著作物を学習に活用したこと自体が著作権侵害だという訴訟が複数進行中です。", zh: "这是更热的争议点，有多起诉讼正在进行，主张未经同意将著作物用于训练本身就构成著作权侵害。", vi: "Đây là điểm tranh cãi nóng hơn nữa, hiện có nhiều vụ kiện đang diễn ra cho rằng việc dùng tác phẩm để huấn luyện mà không được sự đồng ý tự bản thân nó đã là xâm phạm bản quyền.", es: "Este es un punto aún más candente: hay varias demandas en curso que sostienen que usar obras protegidas para el entrenamiento sin consentimiento constituye en sí mismo una infracción de derechos de autor." },
      { speaker: "청취자", kr: "그럼 예술가들이 자기 작품이 학습에 쓰였는지조차 알기 어려운 거 아닌가요? 입증 책임이 너무 불공평한 것 같아요.", en: "So isn't it hard for artists to even know whether their work was used for training? The burden of proof seems terribly unfair.", ja: "それではアーティストたちは自分の作品が学習に使われたかどうかさえ知るのが難しいんじゃないですか? 立証責任があまりにも不公平に思えます。", zh: "那艺术家们连自己的作品是否被用于训练都很难得知吧？举证责任似乎太不公平了。", vi: "Vậy chẳng phải các nghệ sĩ khó mà biết được tác phẩm của mình có bị dùng để huấn luyện hay không sao? Trách nhiệm chứng minh nghe có vẻ quá bất công.", es: "Entonces, ¿no es difícil incluso para los artistas saber si su obra se usó para el entrenamiento? La carga de la prueba parece terriblemente injusta." },
      { speaker: "변호사", kr: "정확한 지적입니다. 그래서 최근에는 기업 측에 학습 데이터 출처를 공개하도록 의무화하자는 입법 논의가 진행되고 있습니다.", en: "That's an accurate point. That's why recent legislative discussions are pushing to require companies to disclose the sources of their training data.", ja: "正確なご指摘です。それで最近は企業側に学習データの出所を公開するよう義務化しようという立法論議が進んでいます。", zh: "指摘得很准确。所以最近正在推进立法讨论，要求企业方公开训练数据的来源。", vi: "Đó là nhận xét rất chính xác. Vì vậy gần đây đang có thảo luận lập pháp để bắt buộc doanh nghiệp công khai nguồn gốc dữ liệu huấn luyện.", es: "Es una observación certera. Por eso recientemente se están llevando a cabo debates legislativos para obligar a las empresas a divulgar el origen de sus datos de entrenamiento." },
      { speaker: "진행자", kr: "결국 기술 발전 속도를 법과 제도가 따라가지 못하고 있다는 인상을 지울 수 없네요.", en: "In the end, one can't shake the impression that law and institutions are failing to keep pace with the speed of technological development.", ja: "結局技術発展のスピードに法と制度が追いついていないという印象を拭えませんね。", zh: "总感觉技术发展的速度，法律和制度还是跟不上啊。", vi: "Rốt cuộc vẫn không thể phủ nhận ấn tượng rằng luật pháp và thể chế đang không theo kịp tốc độ phát triển công nghệ.", es: "Al final, no puedo evitar la impresión de que la ley y las instituciones no logran seguir el ritmo del avance tecnológico." },
      { speaker: "변호사", kr: "동의합니다. 다만 무작정 규제만 강화하기보다는 창작자와 기술 발전이 공존할 수 있는 균형점을 찾는 게 관건이라고 봅니다.", en: "I agree. That said, rather than simply tightening regulation, I think the key lies in finding a balance where creators and technological progress can coexist.", ja: "同感です。ただ、闇雲に規制だけを強化するより、創作者と技術発展が共存できる均衡点を見つけることが肝心だと思います。", zh: "我同意。不过比起一味加强监管，我认为关键在于找到创作者与技术发展能够共存的平衡点。", vi: "Tôi đồng ý. Chỉ là thay vì cứ tăng cường quản lý một cách bừa bãi, tôi nghĩ điều then chốt là tìm ra điểm cân bằng để người sáng tạo và sự phát triển công nghệ có thể cùng tồn tại.", es: "Estoy de acuerdo. Aun así, creo que la clave no está en simplemente reforzar la regulación a ciegas, sino en encontrar un equilibrio donde puedan coexistir los creadores y el avance tecnológico." },
    ],
  },
  {
    id: "phone-c2y-corporate-scandal",
    situationKey: "phone",
    level: "C2",
    title: { en: "A reporter phone-interviews a spokesperson during a corporate scandal", ja: "企業スキャンダルの最中、記者が広報担当者に電話取材する", zh: "企业丑闻发酵中，记者电话采访发言人", vi: "Phóng viên phỏng vấn qua điện thoại người phát ngôn giữa lúc xảy ra bê bối doanh nghiệp", es: "Un periodista entrevista por teléfono a una portavoz durante un escándalo corporativo" },
    lines: [
      { speaker: "기자", kr: "여보세요, 오늘 오전 보도된 갑질 의혹 관련해서 회사 측 공식 입장을 듣고 싶어 전화드렸습니다.", en: "Hello, I'm calling to hear the company's official position on the workplace abuse allegations reported this morning.", ja: "もしもし、今朝報道されたパワハラ疑惑に関して、会社側の公式見解をお伺いしたくてお電話しました。", zh: "喂，是想听听公司方面对今早报道的职场霸凌嫌疑的正式立场，所以打电话过来了。", vi: "A lô, tôi muốn nghe lập trường chính thức của công ty về nghi vấn lạm quyền được đưa tin sáng nay.", es: "Hola, le llamo porque quería conocer la postura oficial de la empresa sobre las acusaciones de abuso de poder reportadas esta mañana." },
      { speaker: "홍보팀", kr: "네, 우선 해당 보도로 심려를 끼쳐드린 점 사과드립니다. 다만 사실관계는 현재 내부 조사 중이라 단정적으로 말씀드리기 어렵습니다.", en: "Yes, first I apologize for the concern caused by that report. However, since the facts are currently under internal investigation, it's difficult to state anything definitively.", ja: "はい、まずその報道でご心配をおかけしたことをお詫び申し上げます。ただ、事実関係は現在内部調査中で断定的に申し上げるのは難しいです。", zh: "是的，首先对该报道给您带来的忧虑表示歉意。不过事实关系目前正在内部调查中，很难做出断定性的说明。", vi: "Vâng, trước tiên chúng tôi xin lỗi vì đã gây lo lắng bởi bài báo đó. Chỉ là sự thật hiện đang được điều tra nội bộ nên khó có thể khẳng định chắc chắn.", es: "Sí, ante todo pedimos disculpas por la preocupación que haya causado esa noticia. Sin embargo, como los hechos aún están bajo investigación interna, es difícil hacer afirmaciones categóricas." },
      { speaker: "기자", kr: "제보자에 따르면 임원이 직원들에게 폭언을 하고 부당한 업무 지시를 내렸다는데, 사실 여부만이라도 확인해 주실 수 있나요?", en: "According to the informant, an executive used abusive language toward employees and gave unfair work directives—can you at least confirm whether that's true?", ja: "提報者によると、役員が職員に暴言を吐いて不当な業務指示を出したとのことですが、事実かどうかだけでも確認していただけますか?", zh: "据举报人称，一名高管对员工恶语相向并下达不合理的工作指令，能不能至少确认一下这是否属实？", vi: "Theo người tố giác, một cán bộ đã lăng mạ nhân viên và đưa ra chỉ thị công việc bất hợp lý, chị có thể xác nhận sự thật đó không ạ?", es: "Según el denunciante, un directivo profirió insultos hacia empleados y dio órdenes de trabajo injustas; ¿podría al menos confirmar si eso es cierto?" },
      { speaker: "홍보팀", kr: "구체적인 사실관계에 대해서는 조사 결과가 나오기 전까지 확인해 드리기 어려운 점 양해 부탁드립니다.", en: "I ask for your understanding that we can't confirm the specific facts until the investigation results are out.", ja: "具体的な事実関係については調査結果が出るまで確認が難しい点、ご理解をお願いします。", zh: "具体的事实关系在调查结果出来之前难以确认，恳请您理解。", vi: "Về sự thật cụ thể, mong anh thông cảm là khó xác nhận trước khi có kết quả điều tra.", es: "Le pido comprensión de que no podemos confirmar los hechos concretos hasta que se conozcan los resultados de la investigación." },
      { speaker: "기자", kr: "그럼 이번 사안이 사실로 드러날 경우, 해당 임원에 대한 조치 계획은 있으신가요?", en: "Then if this matter turns out to be true, is there a plan for action against that executive?", ja: "それでは今回の件が事実だと判明した場合、当該役員に対する措置計画はありますか?", zh: "那如果这件事被证实属实，对该高管有什么处理计划吗？", vi: "Vậy nếu việc này được chứng minh là sự thật, có kế hoạch xử lý đối với cán bộ đó không ạ?", es: "Entonces, si este asunto resulta ser cierto, ¿existe algún plan de acción contra ese directivo?" },
      { speaker: "홍보팀", kr: "조사 결과에 따라 인사위원회를 통해 엄중히 조치할 방침입니다. 어떤 지위에 있든 예외는 없습니다.", en: "Depending on the investigation results, we plan to take strict action through the personnel committee. There will be no exceptions regardless of position.", ja: "調査結果に応じて人事委員会を通じて厳正に措置する方針です。どんな地位であっても例外はありません。", zh: "会根据调查结果，通过人事委员会进行严肃处理，无论地位高低都没有例外。", vi: "Tùy theo kết quả điều tra, chúng tôi sẽ xử lý nghiêm khắc thông qua ủy ban nhân sự. Bất kể ở vị trí nào cũng không có ngoại lệ.", es: "Según los resultados de la investigación, tenemos previsto actuar con severidad a través del comité de personal. No habrá excepciones sin importar el cargo que se ocupe." },
      { speaker: "기자", kr: "직원들 사이에서는 이미 여러 차례 문제 제기가 있었는데 묵살됐다는 증언도 나오고 있습니다. 이 부분은 어떻게 설명하시겠습니까?", en: "There's testimony that employees raised this issue multiple times before, only to be dismissed. How would you explain that?", ja: "職員たちの間ではすでに何度も問題提起があったのに握りつぶされたという証言も出ています。この部分はどう説明されますか?", zh: "员工中已经有证词说，这个问题此前多次被提出却被压了下来，这部分您怎么解释？", vi: "Trong nội bộ nhân viên đã có nhiều lời chứng cho rằng vấn đề này từng được nêu ra nhiều lần nhưng bị ỉm đi, chị giải thích thế nào về điều này ạ?", es: "Hay testimonios de empleados que dicen que este problema ya se había planteado varias veces antes y fue ignorado. ¿Cómo explica esto?" },
      { speaker: "홍보팀", kr: "그 부분도 조사 범위에 포함해서 시스템상 미흡했던 점이 있었는지 함께 점검하고 있습니다.", en: "That aspect is also included in the scope of the investigation, and we're jointly examining whether there were shortcomings in the system.", ja: "その部分も調査範囲に含めて、システム上不十分だった点がなかったか一緒に点検しています。", zh: "那部分也纳入了调查范围，我们正在一并检查制度上是否存在不足之处。", vi: "Phần đó cũng được đưa vào phạm vi điều tra, chúng tôi đang xem xét cùng lúc xem có thiếu sót nào trong hệ thống hay không.", es: "Ese aspecto también forma parte del alcance de la investigación, y estamos examinando conjuntamente si hubo deficiencias en el sistema." },
      { speaker: "기자", kr: "알겠습니다. 조사 결과와 후속 조치는 언제쯤 공개될 예정인가요?", en: "Understood. When are the investigation results and follow-up measures expected to be made public?", ja: "分かりました。調査結果と後続措置はいつ頃公開される予定ですか?", zh: "明白了。调查结果和后续措施预计什么时候公开呢？", vi: "Tôi hiểu rồi. Kết quả điều tra và biện pháp tiếp theo dự kiến sẽ công bố khi nào ạ?", es: "Entendido. ¿Para cuándo se prevé que se hagan públicos los resultados de la investigación y las medidas posteriores?" },
      { speaker: "홍보팀", kr: "늦어도 2주 안에는 결과를 정리해서 공식 발표하겠습니다. 신뢰 회복을 위해 최선을 다하겠습니다.", en: "We'll compile the results and make an official announcement within two weeks at the latest. We'll do our best to restore trust.", ja: "遅くとも2週間以内には結果をまとめて公式発表いたします。信頼回復のため最善を尽くします。", zh: "最晚会在两周之内整理结果并正式公布，我们会尽全力恢复信任。", vi: "Chậm nhất trong hai tuần chúng tôi sẽ tổng hợp kết quả và công bố chính thức. Chúng tôi sẽ cố gắng hết sức để khôi phục niềm tin.", es: "A más tardar en dos semanas, compilaremos los resultados y haremos un anuncio oficial. Haremos todo lo posible por restaurar la confianza." },
    ],
  },
  {
    id: "phone-c2y-euthanasia-debate",
    situationKey: "phone",
    level: "C2",
    title: { en: "A podcast phone panel debates assisted dying legislation", ja: "ポッドキャストのパネルが尊厳死法制化を討論する", zh: "播客座谈会辩论安乐死立法问题", vi: "Ban thảo luận podcast tranh luận về luật hóa quyền được chết trợ giúp", es: "Un panel telefónico de un pódcast debate la legislación sobre la muerte asistida" },
    lines: [
      { speaker: "진행자", kr: "오늘은 조력 존엄사 법제화 논의를 두고 의료윤리학자와 전화로 연결돼 있습니다. 민감한 주제인 만큼 신중하게 다뤄보겠습니다.", en: "Today we're connected by phone with a bioethicist to discuss the legislative debate over assisted dying. Since it's a sensitive topic, we'll handle it carefully.", ja: "今日は尊厳死の法制化議論について、医療倫理学者の方と電話がつながっています。デリケートなテーマなので慎重に扱いたいと思います。", zh: "今天关于协助尊严死亡的立法讨论，我们连线了一位医学伦理学者。因为是敏感话题，我们会谨慎处理。", vi: "Hôm nay chúng tôi kết nối điện thoại với một nhà đạo đức y học để bàn về thảo luận luật hóa quyền được chết một cách tôn nghiêm với sự trợ giúp. Vì là chủ đề nhạy cảm nên chúng tôi sẽ trao đổi thận trọng.", es: "Hoy estamos conectados por teléfono con un bioeticista para hablar del debate legislativo sobre la muerte digna asistida. Al ser un tema sensible, lo trataremos con mucho cuidado." },
      { speaker: "윤리학자", kr: "안녕하세요. 이 논의는 결국 자기결정권과 생명 보호 원칙이 정면으로 충돌하는 지점이라 쉽게 결론 낼 사안이 아닙니다.", en: "Hello. This debate ultimately sits at the point where the right to self-determination directly collides with the principle of life protection, so it's not something to be concluded easily.", ja: "こんにちは。この議論は結局、自己決定権と生命保護の原則が正面から衝突する地点なので、簡単に結論を出せる事案ではありません。", zh: "您好。这个议题终究是自主决定权与生命保护原则正面冲突的地方，不是能轻易下结论的事情。", vi: "Xin chào. Cuộc thảo luận này cuối cùng là điểm mà quyền tự quyết và nguyên tắc bảo vệ sự sống va chạm trực diện, nên không phải vấn đề dễ dàng kết luận.", es: "Buenos días. Este debate, en el fondo, se sitúa en un punto donde el derecho a la autodeterminación choca de frente con el principio de protección de la vida, así que no es algo que se pueda concluir con facilidad." },
      { speaker: "청취자", kr: "여보세요, 저는 말기 환자 가족을 간병한 경험이 있는데요. 본인이 원하는데도 고통을 연장시키는 게 과연 옳은 건지 의문이 들더라고요.", en: "Hello, I've had the experience of caring for a family member with a terminal illness. I really question whether prolonging suffering against the person's own wishes is truly right.", ja: "もしもし、私は末期患者の家族を看病した経験があるんですが。本人が望んでいるのに苦痛を長引かせるのが果たして正しいのか疑問に思いました。", zh: "喂，我有过照顾晚期病人家属的经历。本人明明希望结束痛苦，却要被延长下去，我很怀疑这是否正确。", vi: "A lô, tôi từng có kinh nghiệm chăm sóc người thân bị bệnh giai đoạn cuối. Tôi tự hỏi liệu kéo dài nỗi đau dù bản thân người đó mong muốn kết thúc có thực sự đúng không.", es: "Hola, tengo experiencia cuidando a un familiar con una enfermedad terminal. Me pregunto si de verdad es correcto prolongar el sufrimiento cuando la propia persona lo desea así." },
      { speaker: "윤리학자", kr: "충분히 공감이 가는 경험담입니다. 다만 제도화될 경우 남용 가능성, 특히 취약 계층에 대한 압박 우려도 함께 논의돼야 합니다.", en: "That's an experience I can fully empathize with. But if it's institutionalized, the potential for abuse—especially concerns about pressure on vulnerable groups—must also be discussed.", ja: "十分共感できる経験談です。ただ制度化された場合、悪用の可能性、特に脆弱層への圧力への懸念も一緒に議論されるべきです。", zh: "这是完全能引起共鸣的经历。但如果被制度化，滥用的可能性，尤其是对弱势群体施压的担忧，也需要一并讨论。", vi: "Đó là trải nghiệm rất đáng đồng cảm. Chỉ là nếu được thể chế hóa, khả năng bị lạm dụng, đặc biệt là mối lo về áp lực lên nhóm dễ tổn thương cũng cần được bàn đến.", es: "Es un testimonio con el que puedo empatizar plenamente. Pero si se institucionaliza, también hay que discutir el riesgo de abuso, sobre todo la preocupación por la presión sobre los grupos vulnerables." },
      { speaker: "진행자", kr: "실제로 이미 시행 중인 해외 국가에서는 그런 우려가 현실화된 사례가 있습니까?", en: "In countries where this is already in effect, have those concerns actually materialized in real cases?", ja: "実際にすでに施行中の海外の国ではそういう懸念が現実化した事例がありますか?", zh: "实际上在已经实施的海外国家，那种担忧有变成现实的案例吗？", vi: "Thực tế ở các nước đã áp dụng, có trường hợp nào những lo ngại đó trở thành hiện thực không ạ?", es: "¿Hay casos reales en países donde ya está en vigor en los que esas preocupaciones se hayan materializado?" },
      { speaker: "윤리학자", kr: "일부 국가에서 대상 요건이 점차 확대되면서 논란이 불거진 바 있습니다. 처음엔 말기 환자로 한정했다가 범위가 넓어진 거죠.", en: "In some countries, controversy has arisen as eligibility criteria gradually expanded. It started limited to terminal patients, but the scope broadened over time.", ja: "一部の国で対象要件が徐々に拡大されて論争が起きたことがあります。最初は末期患者に限定していたのが範囲が広がったんです。", zh: "有些国家的适用条件逐渐扩大，引发了争议。最初仅限于晚期患者，后来范围扩大了。", vi: "Ở một số nước, tranh cãi đã nổ ra khi điều kiện đối tượng dần được mở rộng. Ban đầu chỉ giới hạn ở bệnh nhân giai đoạn cuối nhưng phạm vi đã mở rộng dần.", es: "En algunos países ha surgido controversia a medida que los requisitos de elegibilidad se fueron ampliando gradualmente. Al principio se limitaba a pacientes terminales, pero el alcance se fue extendiendo." },
      { speaker: "청취자", kr: "그럼 결국 엄격한 요건과 다중 검증 절차 없이는 도입 자체가 위험하다는 말씀이신 거죠?", en: "So you're saying that introducing it without strict criteria and multi-layered verification procedures would be dangerous in itself?", ja: "それでは結局、厳格な要件と多重検証手続きなしには導入自体が危険だということですね?", zh: "那也就是说，没有严格的条件和多层验证程序，引入本身就是危险的？", vi: "Vậy nghĩa là nếu không có điều kiện nghiêm ngặt và quy trình kiểm chứng nhiều lớp thì việc áp dụng bản thân nó đã nguy hiểm rồi phải không ạ?", es: "Entonces, ¿al final está diciendo que, sin requisitos estrictos y un proceso de verificación múltiple, implementarlo sería en sí mismo peligroso?" },
      { speaker: "윤리학자", kr: "정확합니다. 자기결정권을 존중하되, 그 결정이 진정 자율적인지 담보할 안전장치가 반드시 선행돼야 한다는 게 제 입장입니다.", en: "Exactly. My position is that while self-determination should be respected, safeguards ensuring that decision is truly autonomous must absolutely come first.", ja: "その通りです。自己決定権を尊重しつつ、その決定が本当に自律的なのかを担保する安全装置が必ず先行すべきというのが私の立場です。", zh: "没错。尊重自主决定权的同时，必须先有确保该决定确实是自主的安全机制，这是我的立场。", vi: "Chính xác. Lập trường của tôi là tôn trọng quyền tự quyết, nhưng nhất thiết phải có cơ chế an toàn đảm bảo quyết định đó thực sự tự chủ đi trước.", es: "Exacto. Mi postura es que, aunque se respete la autodeterminación, deben existir de antemano salvaguardas que garanticen que esa decisión sea realmente autónoma." },
      { speaker: "진행자", kr: "결국 찬반을 떠나 제도 설계의 정교함이 관건이라는 말씀이시네요.", en: "So beyond the for-and-against divide, you're saying the sophistication of institutional design is the key issue.", ja: "結局賛否を離れて、制度設計の精巧さが肝心だということですね。", zh: "也就是说，撇开赞成与反对，制度设计的精细程度才是关键。", vi: "Vậy nói cách khác, bỏ qua chuyện tán thành hay phản đối, điều then chốt là độ tinh vi trong thiết kế thể chế.", es: "Entonces, más allá de estar a favor o en contra, lo que dice es que la clave está en el rigor con que se diseñe el sistema." },
      { speaker: "윤리학자", kr: "네, 성급한 입법보다는 사회적 합의와 정교한 절차 마련이 우선돼야 한다고 봅니다.", en: "Yes, I believe social consensus and careful procedural design should take priority over hasty legislation.", ja: "はい、性急な立法よりは社会的合意と精巧な手続きの整備が優先されるべきだと思います。", zh: "是的，我认为社会共识和周密的程序设计应该优先于仓促立法。", vi: "Vâng, tôi cho rằng đồng thuận xã hội và xây dựng quy trình tinh vi nên được ưu tiên hơn là lập pháp vội vàng.", es: "Sí, creo que un consenso social y un procedimiento cuidadosamente elaborado deberían tener prioridad sobre una legislación precipitada." },
      { speaker: "청취자", kr: "어려운 주제지만 오늘 얘기 들으면서 저도 좀 더 균형 잡힌 시각을 갖게 된 것 같아요. 감사합니다.", en: "It's a difficult topic, but listening today helped me gain a more balanced perspective, I think. Thank you.", ja: "難しいテーマですが、今日のお話を聞いてもう少しバランスの取れた見方ができるようになった気がします。ありがとうございました。", zh: "这是个很难的话题，但听了今天的对话，我感觉自己有了更平衡的看法。谢谢您。", vi: "Đây là chủ đề khó, nhưng nghe cuộc trò chuyện hôm nay tôi cảm thấy mình đã có góc nhìn cân bằng hơn. Cảm ơn ông.", es: "Es un tema difícil, pero escuchando la conversación de hoy siento que he adquirido una visión más equilibrada. Muchas gracias." },
    ],
  },
  {
    id: "phone-c2y-whistleblowing-app",
    situationKey: "phone",
    level: "C2",
    title: { en: "A podcast host interviews a regulator on gig-economy algorithm transparency", ja: "ポッドキャストの司会者がギグエコノミーのアルゴリズム透明性について規制当局者にインタビューする", zh: "播客主持人就零工经济算法透明度采访监管官员", vi: "Người dẫn chương trình podcast phỏng vấn nhà quản lý về minh bạch thuật toán trong kinh tế gig", es: "Un presentador de pódcast entrevista a un regulador sobre la transparencia algorítmica en la economía de plataformas" },
    lines: [
      { speaker: "진행자", kr: "오늘은 배달 플랫폼의 알고리즘 배차 방식에 대한 투명성 논란을 두고 공정거래위원회 관계자와 전화로 얘기 나눠보겠습니다.", en: "Today we'll discuss the transparency controversy over delivery platforms' algorithmic dispatch methods, in a phone conversation with a Fair Trade Commission official.", ja: "今日は配達プラットフォームのアルゴリズム配車方式をめぐる透明性論争について、公正取引委員会の関係者の方と電話でお話しします。", zh: "今天关于外卖平台算法派单方式引发的透明度争议，我们通过电话与公平交易委员会的相关人士探讨。", vi: "Hôm nay chúng tôi sẽ trao đổi qua điện thoại với một cán bộ Ủy ban Thương mại công bằng về tranh cãi minh bạch đối với phương thức phân bổ đơn hàng bằng thuật toán của các nền tảng giao hàng.", es: "Hoy hablaremos por teléfono con un representante de la Comisión de Comercio Justo sobre la polémica en torno a la transparencia del método de asignación algorítmica de pedidos en las plataformas de reparto." },
      { speaker: "관계자", kr: "안녕하세요. 최근 배달 기사들 사이에서 배차 기준이 자의적이라는 민원이 급증하고 있어 저희도 실태 조사에 착수한 상태입니다.", en: "Hello. Complaints from delivery drivers that the dispatch criteria are arbitrary have surged recently, so we've launched a fact-finding investigation on our end as well.", ja: "こんにちは。最近配達員の間で配車基準が恣意的だという苦情が急増していて、私たちも実態調査に着手した状態です。", zh: "您好。最近配送员中关于派单标准随意性的投诉激增，我们也已经着手开展实况调查。", vi: "Xin chào. Gần đây khiếu nại từ các tài xế giao hàng cho rằng tiêu chí phân bổ đơn mang tính tùy tiện đang tăng vọt, nên chúng tôi cũng đã bắt tay vào điều tra thực trạng.", es: "Buenos días. Las quejas de los repartidores sobre la arbitrariedad de los criterios de asignación han aumentado mucho últimamente, así que también hemos iniciado una investigación de la situación." },
      { speaker: "청취자", kr: "여보세요, 저도 배달 일 하는 사람인데요. 왜 어떤 기사한테는 콜이 몰리고 저는 몇 시간씩 대기해야 하는지 이유를 전혀 알 수가 없어요.", en: "Hello, I also work as a delivery driver. I have no idea why calls flood to some drivers while I have to wait for hours.", ja: "もしもし、私も配達の仕事をしている者ですが。なぜある配達員には注文が集中して、私は何時間も待たなければならないのか全く理由が分かりません。", zh: "喂，我也是做配送工作的。为什么有的配送员订单接连不断，我却要等好几个小时，完全搞不清楚原因。", vi: "A lô, tôi cũng là người làm nghề giao hàng. Tôi hoàn toàn không biết lý do vì sao có tài xế nhận đơn liên tục còn tôi phải chờ mấy tiếng đồng hồ.", es: "Hola, yo también trabajo en el reparto. No entiendo en absoluto por qué a algunos repartidores les llegan pedidos sin parar y yo tengo que esperar horas." },
      { speaker: "관계자", kr: "그 부분이 핵심 쟁점입니다. 플랫폼 측은 영업비밀이라며 알고리즘 세부 기준 공개를 거부하고 있는 상황이거든요.", en: "That's exactly the core issue. The platform is refusing to disclose the detailed algorithmic criteria, citing trade secrets.", ja: "その部分が核心の争点です。プラットフォーム側は営業秘密だとしてアルゴリズムの詳細基準の公開を拒否している状況です。", zh: "那正是核心争议点。平台方以营业秘密为由，拒绝公开算法的详细标准。", vi: "Đó chính là điểm mấu chốt của tranh cãi. Phía nền tảng lấy lý do bí mật kinh doanh để từ chối công khai tiêu chí chi tiết của thuật toán.", es: "Ese es precisamente el punto clave. La plataforma se niega a revelar los criterios detallados del algoritmo alegando que son secretos comerciales." },
      { speaker: "진행자", kr: "영업비밀이라는 논리가 법적으로 인정될 수 있는 겁니까? 노동 조건과 직결된 문제인데요.", en: "Can that trade-secret argument actually hold up legally? This is directly tied to working conditions.", ja: "営業秘密という論理が法的に認められ得るんですか? 労働条件と直結する問題ですが。", zh: "营业秘密这种说法在法律上能站得住脚吗？这可是和劳动条件直接相关的问题。", vi: "Lý lẽ bí mật kinh doanh đó có thể được công nhận về mặt pháp lý không ạ? Vì đây là vấn đề liên quan trực tiếp đến điều kiện lao động.", es: "¿Puede sostenerse legalmente ese argumento de secreto comercial? Es un asunto directamente relacionado con las condiciones laborales." },
      { speaker: "관계자", kr: "저희 입장은 전면 공개가 아니더라도, 최소한 배차에 영향을 주는 핵심 변수만큼은 설명할 의무가 있다는 겁니다.", en: "Our position is that even without full disclosure, there's at least an obligation to explain the key variables that affect dispatch.", ja: "私たちの立場としては、全面公開でなくても、少なくとも配車に影響を与える核心変数だけは説明する義務があるということです。", zh: "我们的立场是，即使不全面公开，至少对影响派单的核心变量应负有说明义务。", vi: "Lập trường của chúng tôi là dù không công khai toàn bộ, ít nhất cũng có nghĩa vụ giải thích các biến số cốt lõi ảnh hưởng đến việc phân bổ đơn hàng.", es: "Nuestra postura es que, aunque no sea una divulgación total, al menos existe la obligación de explicar las variables clave que afectan la asignación de pedidos." },
      { speaker: "청취자", kr: "그럼 실제로 그런 설명 의무를 강제할 법안이 마련되고 있는 건가요?", en: "So is legislation actually being prepared to enforce that explanation obligation?", ja: "それでは実際にそういう説明義務を強制する法案が用意されているんですか?", zh: "那实际上有正在准备强制这种说明义务的法案吗？", vi: "Vậy thực tế có dự luật nào đang được chuẩn bị để bắt buộc nghĩa vụ giải thích đó không ạ?", es: "Entonces, ¿se está preparando realmente una ley que obligue a cumplir con ese deber de explicación?" },
      { speaker: "관계자", kr: "네, 알고리즘 설명 요구권을 명문화하는 개정안이 국회에 발의돼 있고, 저희도 의견서를 제출한 상태입니다.", en: "Yes, an amendment codifying the right to demand algorithmic explanations has been introduced in the National Assembly, and we've submitted our written opinion as well.", ja: "はい、アルゴリズム説明要求権を明文化する改正案が国会に発議されていて、私たちも意見書を提出した状態です。", zh: "是的，明文规定算法说明请求权的修正案已在国会提出，我们也已经提交了意见书。", vi: "Vâng, dự luật sửa đổi quy định thành văn về quyền yêu cầu giải thích thuật toán đã được trình lên Quốc hội, và chúng tôi cũng đã nộp ý kiến bằng văn bản.", es: "Sí, hay un proyecto de reforma en la Asamblea Nacional que codifica el derecho a exigir una explicación del algoritmo, y nosotros también hemos presentado nuestro dictamen." },
      { speaker: "진행자", kr: "법안이 통과되기까지는 시일이 걸릴 텐데, 그동안 기사들이 취할 수 있는 대응은 없을까요?", en: "It'll take time before the bill passes—is there anything drivers can do in the meantime?", ja: "法案が通過するまで時間がかかると思いますが、その間配達員が取れる対応はないでしょうか?", zh: "法案通过应该还需要时间，在此期间配送员有什么可以采取的应对措施吗？", vi: "Chắc phải mất thời gian mới thông qua được luật, trong lúc đó các tài xế có thể làm gì được không ạ?", es: "Va a llevar tiempo hasta que se apruebe la ley; mientras tanto, ¿no hay nada que los repartidores puedan hacer?" },
      { speaker: "관계자", kr: "일단 불합리한 배차 사례를 구체적으로 기록해서 저희 신고 센터에 제출해 주시면, 집단 민원으로 조사에 반영할 수 있습니다.", en: "For now, if you document specific cases of unreasonable dispatch and submit them to our complaint center, we can reflect them in the investigation as collective grievances.", ja: "とりあえず不合理な配車事例を具体的に記録して私たちの申告センターに提出していただければ、集団苦情として調査に反映することができます。", zh: "首先请把不合理的派单案例具体记录下来提交到我们的举报中心，我们可以将其作为集体投诉纳入调查。", vi: "Trước mắt nếu anh/chị ghi lại cụ thể các trường hợp phân bổ đơn bất hợp lý rồi nộp cho trung tâm khiếu nại của chúng tôi, chúng tôi có thể đưa vào điều tra dưới dạng khiếu nại tập thể.", es: "Por lo pronto, si documentan casos concretos de asignación irrazonable y los presentan en nuestro centro de denuncias, podemos incorporarlos a la investigación como quejas colectivas." },
    ],
  },
  {
    id: "phone-c2y-historic-district",
    situationKey: "phone",
    level: "C2",
    title: { en: "A call-in panel debates preserving a historic district versus new development", ja: "ラジオのパネルが歴史地区の保存と新規開発を討論する", zh: "电台座谈会辩论历史街区保护与新开发", vi: "Ban thảo luận gọi vào tranh luận về bảo tồn khu phố lịch sử so với phát triển mới", es: "Un panel de radio abierto al público debate la preservación de un barrio histórico frente a un nuevo desarrollo" },
    lines: [
      { speaker: "진행자", kr: "오늘은 근대 문화유산이 남아 있는 구도심 보존 문제를 두고 건축사학자와 통화 연결돼 있습니다.", en: "Today we're on the phone with an architectural historian to discuss preserving the old downtown, which still holds modern-era cultural heritage.", ja: "今日は近代文化遺産が残る旧市街の保存問題について、建築史学者の方と電話がつながっています。", zh: "今天关于保留近代文化遗产的旧市中心保护问题，我们连线了一位建筑史学家。", vi: "Hôm nay chúng tôi kết nối điện thoại với một nhà sử học kiến trúc để bàn về vấn đề bảo tồn khu trung tâm cũ còn lưu giữ di sản văn hóa cận đại.", es: "Hoy estamos conectados por teléfono con un historiador de la arquitectura para hablar de la conservación del centro histórico, donde aún se conserva patrimonio cultural moderno." },
      { speaker: "학자", kr: "안녕하세요. 이 지역 건축물들은 단순한 노후 건물이 아니라 근대화 과정을 보여주는 귀중한 사료라고 봐야 합니다.", en: "Hello. The buildings in this area shouldn't be viewed as merely aging structures, but as precious historical records documenting the modernization process.", ja: "こんにちは。この地域の建築物は単なる老朽建物ではなく、近代化の過程を示す貴重な史料と見るべきです。", zh: "您好。这个地区的建筑不该只被视为老旧建筑，而应看作展现近代化进程的珍贵史料。", vi: "Xin chào. Các công trình kiến trúc ở khu vực này không nên xem đơn thuần là những tòa nhà cũ kỹ, mà nên coi là sử liệu quý giá cho thấy quá trình hiện đại hóa.", es: "Buenos días. Los edificios de esta zona no deben verse como simples construcciones antiguas, sino como material histórico valioso que documenta el proceso de modernización." },
      { speaker: "청취자", kr: "여보세요, 저는 그 동네에 사는 주민인데요. 낡은 건물 붙잡고 있는 사이에 안전 문제는 누가 책임지나요? 지진 나면 무너질 텐데요.", en: "Hello, I'm a resident of that neighborhood. While everyone clings to these old buildings, who's responsible for the safety issues? They'd collapse in an earthquake.", ja: "もしもし、私はその街に住んでいる住民ですが。古い建物にこだわっている間、安全問題は誰が責任を取るんですか? 地震が起きたら崩れますよ。", zh: "喂，我是住在那条街上的居民。大家一直死守着旧建筑的时候，安全问题谁来负责呢？地震一来是会倒塌的。", vi: "A lô, tôi là cư dân sống ở khu đó. Trong lúc giữ khư khư những tòa nhà cũ, ai chịu trách nhiệm về vấn đề an toàn? Động đất mà xảy ra là sập đấy.", es: "Hola, soy vecino de ese barrio. Mientras se aferran a edificios viejos, ¿quién se responsabiliza de la seguridad? Si hay un terremoto, se derrumbarán." },
      { speaker: "학자", kr: "타당한 우려입니다. 다만 전면 철거가 아니라 내진 보강을 병행한 리모델링으로도 안전과 보존을 동시에 달성할 수 있습니다.", en: "That's a valid concern. But rather than full demolition, remodeling combined with seismic reinforcement could achieve both safety and preservation at the same time.", ja: "妥当な懸念です。ただ全面撤去ではなく、耐震補強を並行したリモデリングでも、安全と保存を同時に達成できます。", zh: "这是合理的担忧。不过不用全面拆除，通过配合抗震加固的翻新，也能同时实现安全与保护。", vi: "Đó là mối lo hợp lý. Chỉ là thay vì phá dỡ hoàn toàn, việc tân trang kết hợp gia cố chống động đất có thể đạt được cả an toàn lẫn bảo tồn.", es: "Es una preocupación válida. Pero en lugar de una demolición total, una remodelación combinada con refuerzo antisísmico puede lograr al mismo tiempo seguridad y conservación." },
      { speaker: "진행자", kr: "그런 방식은 비용이 상당할 텐데, 재원은 어떻게 마련해야 한다고 보십니까?", en: "That approach would be quite costly—how do you think the funding should be secured?", ja: "そういう方式はかなりの費用がかかると思いますが、財源はどう用意すべきだとお考えですか?", zh: "那种方式应该需要相当高的费用吧，您认为财源该怎么筹措？", vi: "Cách đó chắc chi phí sẽ rất lớn, ông nghĩ nên huy động nguồn tài chính bằng cách nào ạ?", es: "Ese método debe de ser bastante costoso; ¿cómo cree que debería financiarse?" },
      { speaker: "학자", kr: "국비와 지방비 매칭 펀드 형태로 지원하고, 일부는 문화유산 기금을 활용하는 방안이 해외 사례에서도 통용되고 있습니다.", en: "Support in the form of matched national and local funds, combined with the use of cultural heritage funds for part of it, is a common approach seen in overseas cases as well.", ja: "国費と地方費のマッチングファンドの形で支援して、一部は文化遺産基金を活用する案が海外事例でも通用しています。", zh: "以国家资金和地方资金配套基金的形式提供支持，部分利用文化遗产基金，这种方案在海外案例中也很常见。", vi: "Hỗ trợ dưới dạng quỹ đối ứng giữa ngân sách trung ương và địa phương, một phần dùng quỹ di sản văn hóa, đây là cách phổ biến ở các trường hợp nước ngoài.", es: "Apoyo mediante fondos de contrapartida entre el presupuesto nacional y el local, y en parte recurriendo a fondos de patrimonio cultural, es un método que también se usa en casos del extranjero." },
      { speaker: "청취자", kr: "그렇게 돈 들여서 보존한다 쳐도, 상권이 죽어가는 건 어떻게 해결하나요? 관광객만 지나가고 정작 주민들은 떠나고 있어요.", en: "Even granting that money is spent to preserve it, how do you solve the dying commercial district? Only tourists pass through while residents are actually leaving.", ja: "そうやってお金をかけて保存したとしても、商圏が衰退していくのはどう解決するんですか? 観光客だけ通り過ぎて肝心の住民は出て行っていますよ。", zh: "就算那样花钱保护下来，商圈日益萧条又该怎么解决？只有游客路过，居民却真的在离开。", vi: "Dù có bỏ tiền ra bảo tồn như vậy, thì vấn đề thương mại đang chết dần giải quyết thế nào ạ? Chỉ có khách du lịch đi ngang qua còn cư dân thực sự lại đang rời đi.", es: "Aun suponiendo que se conserve gastando ese dinero, ¿cómo se resuelve el hecho de que el comercio se esté muriendo? Solo pasan turistas y los vecinos, en cambio, se están yendo." },
      { speaker: "학자", kr: "정확한 지적입니다. 보존과 병행해서 지역 상인 우선 입점권이나 임대료 안정화 정책이 함께 설계되지 않으면 속 빈 강정이 될 뿐입니다.", en: "That's an accurate point. Unless priority tenancy rights for local merchants or rent stabilization policies are designed alongside preservation, it'll amount to an empty shell.", ja: "正確なご指摘です。保存と並行して地域商人優先入店権や賃料安定化政策が一緒に設計されなければ、中身のない見掛け倒しになるだけです。", zh: "这个指摘很准确。如果不在保护的同时设计地方商户优先入驻权或租金稳定化政策，那就只会是徒有其表的空架子。", vi: "Đó là nhận xét rất chính xác. Nếu không thiết kế song song quyền ưu tiên thuê mặt bằng cho tiểu thương địa phương hay chính sách ổn định giá thuê cùng với bảo tồn, thì chỉ là cái vỏ rỗng tuếch thôi.", es: "Es una observación certera. Si no se diseñan junto con la conservación medidas como el derecho preferente de arrendamiento para comerciantes locales o políticas de estabilización de alquileres, todo quedará en un cascarón vacío." },
      { speaker: "진행자", kr: "결국 보존이냐 개발이냐의 이분법보다는 두 가치를 어떻게 조화시키느냐가 관건이라는 말씀이시네요.", en: "So in the end, the key isn't the binary of preservation versus development, but how to harmonize both values.", ja: "結局保存か開発かの二分法よりは、その二つの価値をどう調和させるかが肝心だということですね。", zh: "看来关键不在于保护还是开发的二分法，而在于如何调和这两种价值。", vi: "Vậy cuối cùng, thay vì phân đôi giữa bảo tồn hay phát triển, điều then chốt là làm sao hài hòa được hai giá trị đó.", es: "Entonces, al final, más que la dicotomía entre conservar o desarrollar, lo que importa es cómo armonizar ambos valores." },
      { speaker: "학자", kr: "네, 그리고 그 과정에 반드시 주민들의 목소리가 정책 설계 단계부터 반영돼야 지속 가능한 결과로 이어질 수 있습니다.", en: "Yes, and residents' voices absolutely need to be reflected from the policy-design stage onward for the outcome to be sustainable.", ja: "はい、そしてその過程に必ず住民の声が政策設計の段階から反映されてこそ、持続可能な結果につながることができます。", zh: "是的，而且这个过程中一定要从政策设计阶段就反映居民的声音，这样才能带来可持续的结果。", vi: "Vâng, và trong quá trình đó nhất định phải phản ánh tiếng nói của cư dân ngay từ giai đoạn thiết kế chính sách, thì mới có thể dẫn đến kết quả bền vững.", es: "Sí, y en ese proceso las voces de los vecinos deben reflejarse sin falta desde la etapa de diseño de la política para que el resultado sea realmente sostenible." },
    ],
  },
];

